  'about.bookshopLeadIn': "ਸਾਡੀ ਕਿਤਾਬਾਂ ਦੀ ਦੁਕਾਨ ਚਲਾਉਣ ਵਾਲੇ ਉਸੇ ਛੋਟੇ ਕਾਰੋਬਾਰ ਦੁਆਰਾ ਬਣਾਇਆ ਗਿਆ:",
  "about.eyebrow": "Luminous StockHaven ਬਾਰੇ",
  "about.pageTitle": "Luminous StockHaven — ਸਾਡੇ ਬਾਰੇ",
  "about.founderHeading": "📖 ਸੰਸਥਾਪਕ ਬਾਰੇ",
  "about.founder.p1": "ਸਤਿ ਸ੍ਰੀ ਅਕਾਲ, ਮੈਂ ਕੌਨਸੇਪਸੀਓਨ ਹਾਂ, Luminous StockHaven ਦੀ ਸੰਸਥਾਪਕ।",
  "about.founder.p2": "ਮੈਂ ਕਿਸੇ ਵੱਡੀ ਟੈਕ ਕੰਪਨੀ ਤੋਂ ਨਹੀਂ ਆਈ, ਅਤੇ ਮੈਂ ਕਿਸੇ ਕਾਰਪੋਰੇਟ ਦਫ਼ਤਰ ਵਿੱਚ ਨਹੀਂ ਬੈਠਦੀ। ਮੈਂ ਇੱਕ ਛੋਟੀ ਪਰਚੂਨ ਦੁਕਾਨਦਾਰ ਹਾਂ, ਬਿਲਕੁਲ ਤੁਹਾਡੇ ਵਾਂਗ। ਮੈਂ ਪੰਜ ਈ-ਕਾਮਰਸ ਦੁਕਾਨਾਂ ਚਲਾਉਂਦੀ ਹਾਂ, ਜੋ ਕਿਤਾਬਾਂ ਅਤੇ ਕਿਤਾਬ-ਪ੍ਰੇਮੀਆਂ ਲਈ ਹੱਥ ਨਾਲ ਬਣੀਆਂ ਚੀਜ਼ਾਂ ਵਿੱਚ ਮਾਹਰ ਹਨ।\nਬਹੁਤ ਸਾਰੇ ਸੁਤੰਤਰ ਪਰਚੂਨ ਵਿਕਰੇਤਾਵਾਂ ਵਾਂਗ, ਮੈਂ ਇੱਕ ਟੁੱਟਣ ਵਾਲੇ ਮੋੜ ਤੇ ਪਹੁੰਚ ਗਈ ਸੀ ਜਦੋਂ ਮੈਂ ਕਈ ਥਾਵਾਂ ਦੀ ਇਨਵੈਂਟਰੀ ਸੰਭਾਲਣ, ਪ੍ਰਕਾਸ਼ਕਾਂ ਦੇ ISBN ਨੂੰ ਆਪਣੇ ਹੱਥ ਨਾਲ ਬਣੇ SKU ਦੇ ਨਾਲ-ਨਾਲ ਟਰੈਕ ਕਰਨ, ਅਤੇ ਅੜਚਣ ਵਾਲੀਆਂ ਸਪ੍ਰੈਡਸ਼ੀਟਾਂ ਨਾਲ ਸਪਲਾਇਰ ਆਰਡਰ ਸੰਭਾਲਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰ ਰਹੀ ਸੀ। ਜਦੋਂ ਮੈਂ ਮਦਦ ਲਈ ਕੋਈ ਐਪ ਲੱਭੀ, ਤਾਂ ਮੈਂ ਛੇ ਵੱਖ-ਵੱਖ ਵਿਕਲਪ ਅਜ਼ਮਾਏ। ਹਰ ਇੱਕ ਜਾਂ ਤਾਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਅਧੂਰਾ ਸੀ, ਜਾਂ ਅਵਿਸ਼ਵਾਸ਼ਯੋਗ ਤੌਰ ਤੇ ਉਲਝਣ ਵਾਲਾ ਸੀ, ਜਾਂ ਲੁਟੇਰਾ ਸੀ — ਬੁਨਿਆਦੀ ਸੰਦਾਂ ਲਈ ਮਹੀਨੇ ਦੇ ਸੈਂਕੜੇ ਡਾਲਰ ਵਸੂਲਦੇ ਸਨ।",
  "about.founder.p3": "ਸੁਤੰਤਰ ਸਿਰਜਣਹਾਰਾਂ ਦਾ ਸ਼ੋਸ਼ਣ ਕਰਨ ਵਾਲੇ ਉਦਯੋਗ ਤੋਂ ਨਿਰਾਸ਼ ਹੋ ਕੇ, ਮੈਂ ਆਪਣਾ ਹੱਲ ਖੁਦ ਬਣਾਉਣ ਦਾ ਫੈਸਲਾ ਕੀਤਾ। ਮੈਂ Luminous StockHaven ਲੋੜ ਵਿੱਚੋਂ ਬਣਾਇਆ, ਤਾਂ ਜੋ ਮੈਂ ਆਪਣੇ ਕਾਰੋਬਾਰ ਸਾਫ਼-ਸੁਥਰੇ, ਕੁਸ਼ਲਤਾ ਨਾਲ ਅਤੇ ਪੂਰੀ ਮਾਨਸਿਕ ਸ਼ਾਂਤੀ ਨਾਲ ਚਲਾ ਸਕਾਂ।",
  "about.founder.p4": "ਮੈਂ ਇਸ ਪਲੇਟਫਾਰਮ ਨੂੰ ਇਮਾਨਦਾਰ, ਕਿਫਾਇਤੀ ਕੀਮਤ ਤੇ ਜਨਤਾ ਲਈ ਖੋਲ੍ਹਣ ਦਾ ਫੈਸਲਾ ਕੀਤਾ, ਕਿਉਂਕਿ ਹਰ ਛੋਟਾ ਦੁਕਾਨਦਾਰ ਅਜਿਹੇ ਸੰਦਾਂ ਦਾ ਹੱਕਦਾਰ ਹੈ ਜੋ ਸੱਚਮੁੱਚ ਕੰਮ ਕਰਦੇ ਹਨ, ਆਪਣੀ ਕਮਾਈ ਨੂੰ ਜੋਖਮ ਵਿੱਚ ਪਾਏ ਬਿਨਾਂ। ਅਸੀਂ ਸੁਤੰਤਰ ਤੌਰ ਤੇ ਮਾਲਕੀ ਵਾਲੇ ਹਾਂ, ਆਪਣੇ ਭਾਈਚਾਰੇ ਦੀ ਜ਼ੋਰਦਾਰ ਰੱਖਿਆ ਕਰਦੇ ਹਾਂ, ਅਤੇ ਇੱਕ ਪਰਚੂਨ ਵਿਕਰੇਤਾ ਦੁਆਰਾ, ਪਰਚੂਨ ਵਿਕਰੇਤਾਵਾਂ ਲਈ ਬਣਾਏ ਗਏ ਹਾਂ।",
  "notice.ariaLabel": "ਟ੍ਰੇਡਮਾਰਕ ਅਤੇ ਕਾਪੀਰਾਈਟ ਸੂਚਨਾ",
  "notice.heading": "🛡️ ਪਰਚੂਨ ਵਿਕਰੇਤਾਵਾਂ ਲਈ ਬਣਾਇਆ, ਕਾਰਪੋਰੇਟ ਗਿੱਧਾਂ ਲਈ ਅਨਮੋਲ",
  "notice.intro": "ਮੈਂ ਇਹ ਐਪ ਇਸ ਲਈ ਬਣਾਈ ਕਿਉਂਕਿ ਮੈਂ 5 ਦੁਕਾਨਾਂ ਚਲਾਉਂਦੀ ਹਾਂ ਅਤੇ ਸੈਂਕੜੇ ਡਾਲਰ ਦੇ ਉਲਝਣ ਵਾਲੇ ਸਾਫਟਵੇਅਰ ਨਾਲ ਠੱਗੇ ਜਾਣ ਤੋਂ ਥੱਕ ਗਈ ਸੀ। ਇਹ ਐਪ ਸੁਤੰਤਰ ਕਲਾਕਾਰਾਂ, ਕਾਰੀਗਰਾਂ, ਕਿਤਾਬ ਵਿਕਰੇਤਾਵਾਂ ਅਤੇ ਸਥਾਨਕ ਦੁਕਾਨਾਂ ਦੀ ਰੱਖਿਆ ਲਈ ਬਣਾਈ ਗਈ ਸੀ।",
  "notice.legalHeading": "ਪ੍ਰਤੀਯੋਗੀਆਂ ਅਤੇ ਨਕਲਚੀਆਂ ਲਈ ਕਾਨੂੰਨੀ ਸੂਚਨਾ:",
  "notice.legalBody": "ਅਸੀਂ ਬਾਜ਼ਾਰ ਤੇ ਸਰਗਰਮੀ ਨਾਲ ਨਜ਼ਰ ਰੱਖਦੇ ਹਾਂ। ਸਾਡੇ ਪਲੇਟਫਾਰਮ ਦਾ ਡਾਟਾ ਕੱਢਣ, ਸਾਡੀਆਂ ਮਾਲਕੀ ਵਾਲੀਆਂ ਕਾਰਜ-ਪ੍ਰਣਾਲੀਆਂ ਦੀ ਨਕਲ ਕਰਨ, ਜਾਂ ਸਾਡੀ ਬੌਧਿਕ ਸੰਪਤੀ ਦੀ ਉਲੰਘਣਾ ਕਰਨ ਦੀ ਕੋਈ ਵੀ ਕੋਸ਼ਿਸ਼ ਤੁਰੰਤ ਅਤੇ ਹਮਲਾਵਰ ਕਾਨੂੰਨੀ ਕਾਰਵਾਈ ਨਾਲ ਮਿਲੇਗੀ।",
  "notice.acquisitionHeading": "ਅਧਿਗ੍ਰਹਿਣ ਫਰਮਾਂ ਅਤੇ ਦਲਾਲਾਂ ਲਈ:",
  "notice.acquisitionBody": "ਮੈਨੂੰ ਈਮੇਲ ਨਾ ਕਰੋ। ਮੈਨੂੰ ਸੁਨੇਹਾ ਨਾ ਭੇਜੋ। ਮੈਨੂੰ 'ਰਣਨੀਤਕ ਨਿਕਾਸ' ਦਾ ਪ੍ਰਸਤਾਵ ਨਾ ਦਿਓ। ਤੁਸੀਂ ਹਜ਼ਾਰਾਂ, ਲੱਖਾਂ, ਕਰੋੜਾਂ ਜਾਂ ਖਰਬਾਂ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰ ਸਕਦੇ ਹੋ — ਜਵਾਬ ਹੈ ਨਹੀਂ। ਤੁਸੀਂ ਇਹ ਐਪ ਸਿਰਫ਼ ਇਸ ਲਈ ਨਹੀਂ ਖਰੀਦੋਗੇ ਕਿ ਮੇਰੇ ਸਾਥੀ ਵਪਾਰੀਆਂ ਲਈ ਕੀਮਤਾਂ ਵਧਾ ਸਕੋ। ਹਰ ਬਿਨ-ਮੰਗਿਆ ਅਧਿਗ੍ਰਹਿਣ ਈਮੇਲ ਤੁਰੰਤ ਸਪੈਮ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਕੀਤਾ ਜਾਵੇਗਾ, ਅਤੇ ਤੁਹਾਡਾ ਡੋਮੇਨ ਸਾਡੇ ਪਲੇਟਫਾਰਮ ਤੋਂ ਸਥਾਈ ਤੌਰ ਤੇ ਰੋਕਿਆ ਜਾਵੇਗਾ। ਆਪਣੀ ਮਿਹਨਤ ਬਚਾਓ।",
  "footer.trademarkLine": "ਅਣਅਧਿਕਾਰਤ ਨਕਲ, ਕਲੋਨਿੰਗ ਜਾਂ ਡਾਟਾ ਕੱਢਣਾ ਸਖਤ ਵਰਜਿਤ ਹੈ।",
