  "welcome.noTrialNote": "ਇਸ ਸਕ੍ਰੀਨ ਨੂੰ ਖੋਲ੍ਹਣ ਨਾਲ ਕੁਝ ਵੀ ਸ਼ੁਰੂ ਨਹੀਂ ਹੁੰਦਾ। ਕੋਈ ਅਜ਼ਮਾਇਸ਼ ਸ਼ੁਰੂ ਨਹੀਂ ਹੁੰਦੀ ਅਤੇ ਕਿਸੇ ਕਾਰਡ ਤੋਂ ਕੋਈ ਚਾਰਜ ਨਹੀਂ ਲਿਆ ਜਾਂਦਾ — ਸੱਤ-ਦਿਨ ਦੀ ਅਜ਼ਮਾਇਸ਼ ਸਿਰਫ਼ ਉਦੋਂ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਕੋਈ ਯੋਜਨਾ ਚੁਣਦੇ ਹੋ ਅਤੇ ਉਸ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੇ ਹੋ। ਦੋਵੇਂ ਵੈੱਬਸਾਈਟ ਯੋਜਨਾਵਾਂ ਵਿੱਚ ਮੋਬਾਈਲ ਸਾਥੀ ਸ਼ਾਮਲ ਹੈ, ਇਸ ਲਈ ਤੁਸੀਂ ਉਹਨਾਂ ਦੇ ਉੱਪਰ ਮਹੀਨਾਵਾਰ ਮੋਬਾਈਲ ਫੀਸ ਕਦੇ ਨਹੀਂ ਦਿੰਦੇ।",
