  "thankYou.subscriptionActive": "ਤੁਹਾਡੀ ਗਾਹਕੀ ਸਰਗਰਮ ਹੈ। ਤੁਸੀਂ ਹੁਣ ਐਪ ਦੀ ਵਰਤੋਂ ਸ਼ੁਰੂ ਕਰ ਸਕਦੇ ਹੋ।",
