  "plans.trialOfferNote": "ਦੋਵੇਂ ਵੈੱਬਸਾਈਟ ਯੋਜਨਾਵਾਂ ਅਤੇ ਮੋਬਾਈਲ ਐਪ ਨਾਲ ਸ਼ਾਮਲ ਹੈ। ਅੱਜ ਕੁਝ ਵੀ ਚਾਰਜ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ — ਗਿਣਤੀ ਉਦੋਂ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਕਿਸੇ ਯੋਜਨਾ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੇ ਹੋ।",
