  "upgrade.title": "ਉਹ ਚੁਣੋ ਜੋ ਤੁਹਾਡੀ ਦੁਕਾਨ ਲਈ ਢੁਕਵਾਂ ਹੋਵੇ",
  "upgrade.pendingCheckoutIntro": "ਇਹ ਨਵਾਂ ਵਰਕਸਪੇਸ Essentials ਤੱਕ ਸੀਮਤ ਹੈ ਜਦ ਤੱਕ ਤੁਸੀਂ ਗਾਹਕੀ ਨਹੀਂ ਚੁਣਦੇ। ਯੋਗ ਨਵੇਂ ਗਾਹਕਾਂ ਨੂੰ ਪ੍ਰਤੀ ਖਾਤਾ ਇੱਕ {days}-ਦਿਨ ਦੀ ਅਜ਼ਮਾਇਸ਼ ਮਿਲ ਸਕਦੀ ਹੈ।",
  "upgrade.intro": "ਯੋਗ ਨਵੇਂ ਗਾਹਕਾਂ ਨੂੰ ਪ੍ਰਤੀ ਖਾਤਾ ਇੱਕ {days}-ਦਿਨ ਦੀ ਅਜ਼ਮਾਇਸ਼ ਮਿਲ ਸਕਦੀ ਹੈ, ਪ੍ਰਤੀ ਯੋਜਨਾ ਇੱਕ ਅਜ਼ਮਾਇਸ਼ ਨਹੀਂ। Essentials ਤੋਂ Business ਵਿੱਚ ਬਦਲਣ ਨਾਲ ਕੋਈ ਹੋਰ ਮੁਫ਼ਤ ਅਜ਼ਮਾਇਸ਼ ਕਦੇ ਸ਼ੁਰੂ ਨਹੀਂ ਹੁੰਦੀ। ਤੁਸੀਂ ਇਸ 'ਤੇ ਹੋ",
  "upgrade.introGrandfathered": " — ਇੱਕ ਪੂਰਾ Business ਵਰਕਸਪੇਸ, ਬਿਨਾਂ ਕਿਸੇ ਚਾਰਜ ਦੇ।",
  "upgrade.introTrial": " (ਅਜ਼ਮਾਇਸ਼)।",
  "upgrade.introPeriod": "।",
  "upgrade.pastDueTitle": "ਭੁਗਤਾਨ ਬਕਾਇਆ",
  "upgrade.pastDueBody": "ਤੁਹਾਡੀ ਆਖਰੀ ਅਦਾਇਗੀ ਪੂਰੀ ਨਹੀਂ ਹੋਈ, ਇਸ ਲਈ ਇਹ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਬਕਾਇਆ ਹੈ। ਅਸਫਲ ਅਦਾਇਗੀ ਤੋਂ 14 ਦਿਨਾਂ ਤੱਕ ਤੁਸੀਂ ਇਸਨੂੰ ਠੀਕ ਕਰਨ ਤੱਕ ਪੂਰੀ ਵਰਤੋਂ ਰੱਖਦੇ ਹੋ। ਜੇ ਇਹ ਠੀਕ ਨਾ ਹੋਈ, ਤਾਂ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਰੱਦ ਹੋ ਜਾਵੇਗੀ, ਵਰਕਸਪੇਸ 15 ਦਿਨਾਂ ਲਈ ਸਿਰਫ਼ ਦੇਖਣ ਯੋਗ ਰਹੇਗੀ, ਅਤੇ ਫਿਰ ਖਾਤਾ ਅਤੇ ਇਸਦੀ ਸਾਰੀ ਜਾਣਕਾਰੀ ਮਿਟਾ ਦਿੱਤੀ ਜਾਵੇਗੀ। ਮਿਟਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਅਦਾਇਗੀ ਕਰਨ ਨਾਲ ਸਭ ਕੁਝ ਵਾਪਸ ਆ ਜਾਂਦਾ ਹੈ। ਹੇਠਾਂ ਆਪਣਾ ਅਦਾਇਗੀ ਤਰੀਕਾ ਅੱਪਡੇਟ ਕਰੋ। ਜੇ ਮਦਦ ਚਾਹੀਦੀ ਹੈ, ਤਾਂ ਈਮੇਲ ਕਰੋ",
  "upgrade.updatePaymentMethod": "ਭੁਗਤਾਨ ਵਿਧੀ ਅੱਪਡੇਟ ਕਰੋ",
  "upgrade.startingPaymentUpdate": "ਭੁਗਤਾਨ ਅੱਪਡੇਟ ਸ਼ੁਰੂ ਹੋ ਰਿਹਾ ਹੈ…",
  "upgrade.paymentUpdateFailed": "ਭੁਗਤਾਨ ਅੱਪਡੇਟ ਸ਼ੁਰੂ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਿਆ।",
  "upgrade.perMonth": "/ ਮਹੀਨਾ",
  "upgrade.taxNote": "ਅਤੇ ਲਾਗੂ ਟੈਕਸ, ਜੇ ਕੋਈ ਹੋਣ। ਤੁਹਾਡੇ ਵੱਲੋਂ ਚਾਰਜ ਨੂੰ ਮਨਜ਼ੂਰੀ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਪ੍ਰਦਾਤਾ ਨੂੰ ਤੁਹਾਡਾ ਸਹੀ ਕੁੱਲ ਵਿਖਾਉਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "upgrade.startSubscription": "ਗਾਹਕੀ ਸ਼ੁਰੂ ਕਰੋ",
  "upgrade.trialCheckedNote": "ਯੋਗ ਨਵੇਂ ਗਾਹਕਾਂ ਨੂੰ ਇੱਕ 7-ਦਿਨ ਦੀ ਮੁਫ਼ਤ ਅਜ਼ਮਾਇਸ਼ ਮਿਲਦੀ ਹੈ — ਚੈੱਕਆਉਟ ਤੋਂ ਪਹਿਲਾਂ ਸਰਵਰ ਦੁਆਰਾ ਜਾਂਚ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।",
  "upgrade.upgradeToBusiness": "Business ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰੋ",
  "upgrade.upgradeNote": "ਉਹੀ ਗਾਹਕੀ, ਕੋਈ ਦੂਜੀ ਅਜ਼ਮਾਇਸ਼ ਨਹੀਂ, ਕੋਈ ਤੁਰੰਤ ਚਾਰਜ ਨਹੀਂ — ਕੀਮਤ ਦਾ ਅੰਤਰ ਤੁਹਾਡੇ ਅਗਲੇ ਇਨਵੌਇਸ 'ਤੇ ਆਵੇਗਾ।",
