  "materials.subtitle": "ਸਟਾਕ ਤੋਂ ਕਿੱਟਾਂ ਪੈਕ ਕਰੋ, ਜਾਂ ਤਿਆਰ ਚੀਜ਼ ਬਣਾਉਣ ਲਈ ਸਮੱਗਰੀ ਵਰਤੋ।",
  "materials.takeApart": "ਖੋਲ੍ਹੋ",
  "materials.takeApartAt": "ਇੱਥੇ ਖੋਲ੍ਹੋ",
