  "materials.takeApartDescription": "ਹਰ ਇਕਾਈ ਸ਼ੈਲਫ਼ ਤੋਂ ਜਾਂਦੀ ਹੈ ਅਤੇ ਉਸ ਦੇ ਹਿੱਸੇ ਉਨ੍ਹਾਂ ਮਾਤਰਾਵਾਂ ਵਿੱਚ ਵਾਪਸ ਆਉਂਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਨਾਲ ਉਹ ਬਣੀ ਸੀ।",
