  "valuation.noRetailPrice": "ਕੋਈ ਪ੍ਰਚੂਨ ਕੀਮਤ ਨਹੀਂ",
  "valuation.footnote": "ਲਾਗਤ ਮੁੱਲ ਹਰ ਉਤਪਾਦ ਦੀ ਮੌਜੂਦਾ ਇਕਾਈ ਲਾਗਤ ਵਰਤਦਾ ਹੈ, ਇਸ ਲਈ ਨਵੀਂ ਕੀਮਤ 'ਤੇ ਪ੍ਰਾਪਤ ਕਰਨਾ ਪੂਰੀ ਸ਼ੈਲਫ਼ ਦਾ ਮੁੜ-ਮੁਲਾਂਕਣ ਕਰਦਾ ਹੈ। ਰੱਖੀਆਂ ਇਕਾਈਆਂ ਅਜੇ ਵੀ ਇੱਥੇ ਗਿਣੀਆਂ ਜਾਂਦੀਆਂ ਹਨ — ਉਹ ਹੱਥ ਵਿੱਚ ਹਨ, ਸਿਰਫ਼ ਕਿਸੇ ਆਰਡਰ ਲਈ ਵਾਅਦਾ ਕੀਤੀਆਂ ਹਨ। ਗੁੰਮ ਪੈਸੇ ਨੂੰ ਕਦੇ ਸਿਫ਼ਰ ਨਹੀਂ ਮੰਨਿਆ ਜਾਂਦਾ; ਅੰਕੜਾ ਪਤਾ ਲੱਗਣ ਤੱਕ ਖੇਤਰ ਖ਼ਾਲੀ ਛੱਡੋ।",
