  "settings.businesses.createDescription": "ਇਹ ਆਪਣੇ ਉਤਪਾਦਾਂ, ਸਥਾਨਾਂ, ਸਪਲਾਇਰਾਂ ਅਤੇ ਖਰੀਦ ਰਿਕਾਰਡਾਂ ਵਾਲਾ ਇੱਕ ਵੱਖਰਾ ਕਾਰੋਬਾਰ ਬਣਾਉਂਦਾ ਹੈ। ਮੌਜੂਦਾ ਕਾਰੋਬਾਰ ਨਹੀਂ ਬਦਲੇ ਜਾਣਗੇ। ਮੁਫ਼ਤ ਲਾਂਚ-ਪਹਿਲਾਂ ਵਰਕਸਪੇਸ ਇੱਕ ਹੋਰ ਮੁਫ਼ਤ ਅਜ਼ਮਾਇਸ਼ ਸ਼ੁਰੂ ਨਹੀਂ ਕਰਦੇ।",
