  "settings.logout": "ਲੌਗ ਆਊਟ",
  "settings.pastDue.body": "ਤੁਹਾਡੀ ਆਖਰੀ ਅਦਾਇਗੀ ਪੂਰੀ ਨਹੀਂ ਹੋਈ। ਅਸਫਲ ਅਦਾਇਗੀ ਤੋਂ 14 ਦਿਨਾਂ ਤੱਕ ਤੁਸੀਂ ਇਸਨੂੰ ਠੀਕ ਕਰਨ ਤੱਕ ਪੂਰੀ ਵਰਤੋਂ ਰੱਖਦੇ ਹੋ। ਜੇ ਇਹ ਠੀਕ ਨਾ ਹੋਈ, ਤਾਂ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਰੱਦ ਹੋ ਜਾਵੇਗੀ, ਵਰਕਸਪੇਸ 15 ਦਿਨਾਂ ਲਈ ਸਿਰਫ਼ ਦੇਖਣ ਯੋਗ ਰਹੇਗੀ, ਅਤੇ ਫਿਰ ਖਾਤਾ ਅਤੇ ਇਸਦੀ ਸਾਰੀ ਜਾਣਕਾਰੀ ਮਿਟਾ ਦਿੱਤੀ ਜਾਵੇਗੀ। ਮਿਟਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਅਦਾਇਗੀ ਕਰਨ ਨਾਲ ਸਭ ਕੁਝ ਵਾਪਸ ਆ ਜਾਂਦਾ ਹੈ। ਜੇ ਤੁਹਾਨੂੰ ਪੱਕਾ ਨਹੀਂ ਕਿ ਕੀ ਕਰਨਾ ਹੈ, ਤਾਂ theluminousbookshop@outlook.com 'ਤੇ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
