  "rewards.give.help": "ਇਨਾਮ ਇੱਕ ਟੀਮ ਮੈਂਬਰ ਕੋਲ ਜਾਂਦੇ ਹਨ। ਮੈਨੇਜਰ ਸਟਾਫ਼ ਨੂੰ ਇਨਾਮ ਦਿੰਦੇ ਹਨ; ਮਾਲਕ ਟੀਮ 'ਤੇ ਕਿਸੇ ਨੂੰ ਵੀ ਇਨਾਮ ਦੇ ਸਕਦਾ ਹੈ।",
