  "rewards.redeem.help": "ਉਹ ਕੋਡ ਟਾਈਪ ਕਰੋ ਜੋ ਟੀਮ ਮੈਂਬਰ ਤੁਹਾਨੂੰ ਦਿਖਾਉਂਦਾ ਹੈ। ਹਰ ਕੋਡ ਇੱਕ ਵਾਰ ਕੰਮ ਕਰਦਾ ਹੈ।",
