  "pos.csv.help": "ਬਿਨਾਂ ਕਨੈਕਸ਼ਨ ਵਾਲੇ ਟਿਲ ਲਈ: ਦਿਨ ਦੀ ਵਿਕਰੀ ਨੂੰ CSV ਵਜੋਂ ਨਿਰਯਾਤ ਕਰੋ ਅਤੇ ਇਸਨੂੰ ਇੱਥੇ ਅੱਪਲੋਡ ਕਰੋ। ਹਰ ਵਿਕਰੀ ਇੱਕ ਵਾਰ ਦਰਜ ਕੀਤੀ ਜਾਂਦੀ ਹੈ — ਇੱਕੋ ਫਾਈਲ ਨੂੰ ਦੁਬਾਰਾ ਅੱਪਲੋਡ ਕਰਨ ਨਾਲ ਕੁਝ ਨਹੀਂ ਬਦਲਦਾ।",
