  "pos.mapping.heldLines": "{count} ਵਿਕਰੀ ਲਾਈਨਾਂ ਉਡੀਕ ਕਰ ਰਹੀਆਂ ਹਨ · {units} ਚੀਜ਼ਾਂ",
