  "pricing.modeRollback": "ਰੋਲਬੈਕ (ਅਸਥਾਈ ਸੇਲ)",
  "pricing.rollbackBadge": "ਰੋਲਬੈਕ",
  "pricing.rollbackHint": "ਆਮ ਕੀਮਤ ਰੱਖੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਸੇਲ ਚੱਲਣ ਤੱਕ ਰੋਲਬੈਕ ਕੀਮਤ ਦੇ ਨਾਲ ਦਿਖਾਈ ਜਾਂਦੀ ਹੈ। ਜਦੋਂ ਖਤਮ ਹੋਣ ਦੀ ਤਾਰੀਖ ਲੰਘ ਜਾਂਦੀ ਹੈ, ਤਾਂ ਕੀਮਤ ਆਪਣੇ ਆਪ ਆਮ ’ਤੇ ਵਾਪਸ ਆ ਜਾਂਦੀ ਹੈ।",
  "pricing.rollbackStarts": "ਰੋਲਬੈਕ {date} ਤੋਂ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ",
  "pricing.salePriceLabel": "ਰੋਲਬੈਕ ਕੀਮਤ",
  "pricing.sectionTitle": "ਵਿਕਰੀ ਕੀਮਤ",
  "pricing.startLabel": "ਸ਼ੁਰੂ",
  "training.lessons.mgr-pricing.step1": "Business ’ਤੇ, ਉਤਪਾਦ ਫਾਰਮ ਵਿੱਚ ਵਿਕਰੀ ਕੀਮਤ ਭਾਗ ਹੁੰਦਾ ਹੈ। ਕਲੀਅਰੈਂਸ ਇੱਕ ਸਥਾਈ ਕਟੌਤੀ ਹੈ — ਤੈਅ ਕਰੋ ਅਤੇ ਇਹ ਰਹਿੰਦੀ ਹੈ। ਰੋਲਬੈਕ ਤਾਰੀਖਾਂ ਵਾਲੀ ਸੇਲ ਹੈ: ਰੋਲਬੈਕ ਕੀਮਤ, ਸ਼ੁਰੂ ਹੋਣ ਦਾ ਦਿਨ ਅਤੇ ਖਤਮ ਹੋਣ ਦਾ ਦਿਨ ਤੈਅ ਕਰੋ।",
  "training.lessons.mgr-pricing.step2": "ਤੁਹਾਨੂੰ ਆਮ ਕੀਮਤ ਕਦੇ ਦੁਬਾਰਾ ਨਹੀਂ ਲਿਖਣੀ ਪੈਂਦੀ: ਇਹ ਉਤਪਾਦ ’ਤੇ ਰਹਿੰਦੀ ਹੈ ਅਤੇ ਉਤਪਾਦ ਸੂਚੀ ਅਤੇ ਸਕੈਨਰ ਵਿੱਚ ਵਿਕਰੀ ਕੀਮਤ ਦੇ ਨਾਲ ਦਿਖਦੀ ਹੈ, ਤਾਂ ਜੋ ਕੋਈ ਵੀ ਦੇਖ ਸਕੇ ਕਿ ਚੀਜ਼ ਆਮ ਤੌਰ ’ਤੇ ਕਿੰਨੇ ਦੀ ਹੈ।",
  "training.lessons.mgr-pricing.step3": "ਜਦੋਂ ਰੋਲਬੈਕ ਸ਼ੁਰੂ ਹੋਵੇ ਤਾਂ ਤਾਜ਼ਾ ਕੀਮਤ ਲੇਬਲ ਛਾਪੋ — ਲੇਬਲ ਉਹ ਕੀਮਤ ਛਾਪਦੇ ਹਨ ਜੋ ਗਾਹਕ ਉਸ ਦਿਨ ਦਿੰਦਾ ਹੈ। ਜਦੋਂ ਖਤਮ ਹੋਣ ਦੀ ਤਾਰੀਖ ਲੰਘ ਜਾਂਦੀ ਹੈ, ਕੀਮਤ ਆਪਣੇ ਆਪ ਆਮ ’ਤੇ ਵਾਪਸ ਆ ਜਾਂਦੀ ਹੈ; ਜਦੋਂ ਤੁਸੀਂ ਸ਼ੈਲਫ਼ ਤਾਜ਼ਾ ਕਰੋ ਤਾਂ ਆਮ ਲੇਬਲ ਦੁਬਾਰਾ ਛਾਪੋ।",
  "training.lessons.mgr-pricing.step4": "ਜੇ ਵਿਕਰੀ ਕੀਮਤ ਭਾਗ ਬੰਦ ਦਿਖੇ, ਤਾਂ ਕਾਰੋਬਾਰ Business ਯੋਜਨਾ ’ਤੇ ਨਹੀਂ ਹੈ — ਵਿਕਰੀ ਕੀਮਤ ਉਸ ਯੋਜਨਾ ਦੀ ਹੈ, ਅਤੇ ਯੋਜਨਾ ਬਦਲਣ ਵਾਲੇ ਮਾਲਕ ਹੁੰਦੇ ਹਨ।",
  "training.lessons.mgr-pricing.title": "ਸੇਲ ਚਲਾਉਣਾ: ਕਲੀਅਰੈਂਸ ਅਤੇ ਰੋਲਬੈਕ",
  "training.lessons.owner-pricing.step1": "ਉਤਪਾਦ ਫਾਰਮ ਵਿੱਚ, ਵਿਕਰੀ ਕੀਮਤ ਅਧੀਨ, ਦੋ ਤਰ੍ਹਾਂ ਦੀਆਂ ਕਟੌਤੀਆਂ ਰਹਿੰਦੀਆਂ ਹਨ। ਕਲੀਅਰੈਂਸ ਸਥਾਈ ਹੈ: ਕਲੀਅਰੈਂਸ ਕੀਮਤ ਤੈਅ ਕਰੋ ਅਤੇ ਇਹ ਉਦੋਂ ਤੱਕ ਘੱਟ ਰਹਿੰਦੀ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਬਦਲਦੇ। ਰੋਲਬੈਕ ਇੱਕ ਅਸਥਾਈ ਸੇਲ ਹੈ — ਸ਼ੁਰੂ ਅਤੇ ਖਤਮ ਤਾਰੀਖਾਂ ਨਾਲ ਇੱਕ ਘੱਟ ਕੀਮਤ, ਵੱਡੇ ਸਟੋਰਾਂ ਤੋਂ ਤੁਸੀਂ ਪਹਿਲਾਂ ਹੀ ਜਾਣਦੇ ਹੋ ਸੇਲਾਂ ਵਾਂਗ।",
  "training.lessons.owner-pricing.step2": "ਆਮ ਕੀਮਤ ਕਦੇ ਮਿਟਾਈ ਨਹੀਂ ਜਾਂਦੀ। ਜਦੋਂ ਰੋਲਬੈਕ ਚੱਲਦਾ ਹੈ, ਐਪ ਵਿਕਰੀ ਕੀਮਤ ਦੇ ਨਾਲ ਆਮ ਕੀਮਤ ਨਾਲ ਦਿਖਾਉਂਦੀ ਹੈ, ਅਤੇ ਛਪੇ ਲੇਬਲ ਵਿਕਰੀ ਕੀਮਤ ਲੈ ਜਾਂਦੇ ਹਨ, ਤਾਂ ਜੋ ਸ਼ੈਲਫ਼ ਅਤੇ ਕੈਸ਼ ਮੇਲ ਖਾਣ।",
  "training.lessons.owner-pricing.step3": "ਜਦੋਂ ਖਤਮ ਹੋਣ ਦੀ ਤਾਰੀਖ ਲੰਘ ਜਾਂਦੀ ਹੈ, ਕੀਮਤ ਆਪਣੇ ਆਪ ਆਮ ’ਤੇ ਵਾਪਸ ਆ ਜਾਂਦੀ ਹੈ — ਕੁਝ ਯਾਦ ਨਹੀਂ ਰੱਖਣਾ, ਕੁਝ ਵਾਪਸ ਨਹੀਂ ਕਰਨਾ। ਜੋ ਰੋਲਬੈਕ ਅਜੇ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋਇਆ, ਉਹ ਉਤਪਾਦ ਸੂਚੀ ’ਤੇ ਹੀ ਆਪਣੀ ਸ਼ੁਰੂਆਤ ਤਾਰੀਖ ਦੱਸਦਾ ਹੈ।",
  "training.lessons.owner-pricing.step4": "ਵਿਕਰੀ ਕੀਮਤ Business ਯੋਜਨਾ ਦੀ ਵਿਸ਼ੇਸ਼ਤਾ ਹੈ। Essentials ’ਤੇ ਖੇਤਰ ਬੰਦ ਰਹਿੰਦੇ ਹਨ, ਅਤੇ ਜੇ ਕੋਈ ਕਾਰੋਬਾਰ Essentials ’ਤੇ ਜਾ ਕੇ ਵਾਪਸ ਆਏ, ਤਾਂ ਉਸਦੀ ਕਲੀਅਰੈਂਸ ਅਤੇ ਰੋਲਬੈਕ ਸੈਟਿੰਗ ਉੱਥੇ ਹੀ ਰਹਿੰਦੀ ਹੈ, ਬਿਲਕੁਲ ਜਿਵੇਂ ਛੱਡੀ ਗਈ ਸੀ।",
  "training.lessons.owner-pricing.title": "ਕਲੀਅਰੈਂਸ ਅਤੇ ਰੋਲਬੈਕ ਕੀਮਤ (Business ਯੋਜਨਾ)",
  "plansLib.includes.shippingLabels": "ਗਾਹਕ ਆਰਡਰਾਂ ਲਈ 4×6 ਸ਼ਿਪਿੰਗ ਲੇਬਲ — ਜਾਂ ਆਪਣੇ ਕੈਰੀਅਰ ਦਾ ਲੇਬਲ ਫਾਈਲ ਵਿੱਚ ਰੱਖੋ",
