  "print.shippingNote": "ਜੇ ਆਰਡਰ ਵਿੱਚ ਭੇਜਣ ਦਾ ਪਤਾ ਹੈ, ਤਾਂ ਉਹ ਆਰਡਰ ਤੋਂ ਭਰ ਜਾਂਦਾ ਹੈ। ਤੁਸੀਂ ਇੱਥੇ ਜੋ ਲਿਖਦੇ ਹੋ ਉਹ ਇੱਕ ਵਾਰ ਛਪਦਾ ਹੈ ਅਤੇ ਕਦੇ ਵਾਪਸ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾਂਦਾ।",
