  "print.carrier.desc": "ਡਾਕ ਖਰਚ ਕੈਰੀਅਰ ਤੋਂ ਖਰੀਦੋ, ਜਿਵੇਂ ਤੁਸੀਂ ਅੱਜ ਕਰਦੇ ਹੋ — ਇਹ ਐਪ ਕਦੇ ਡਾਕ ਖਰਚ ਨਹੀਂ ਵੇਚਦਾ, ਇਸ ਲਈ ਜੋ ਕੀਮਤ ਤੁਸੀਂ ਦਿੰਦੇ ਹੋ ਉਹ ਹਮੇਸ਼ਾ ਕੈਰੀਅਰ ਦੀ ਆਪਣੀ ਕੀਮਤ ਹੁੰਦੀ ਹੈ। ਲੇਬਲ ਫਾਈਲ ਇੱਥੇ ਸਾਂਭੋ ਅਤੇ ਇਹ ਇਸ ਆਰਡਰ ਉੱਤੇ ਹਮੇਸ਼ਾ ਰਹੇਗੀ: ਤੁਹਾਡਾ ਰਿਕਾਰਡ, ਜੇ ਕੁਝ ਹੋ ਜਾਵੇ ਤਾਂ ਹੱਥ ਵਿੱਚ।",
