  "print.carrier.badType": "ਉਹ ਫਾਈਲ ਕੰਮ ਨਹੀਂ ਕਰੇਗੀ — PDF, PNG ਜਾਂ JPG ਲੇਬਲ ਚੁਣੋ।",
