  "print.carrier.pickOrderFirst": "ਉੱਪਰ ਇੱਕ ਆਰਡਰ ਚੁਣੋ, ਫਿਰ ਇਸ ਦਾ ਕੈਰੀਅਰ ਲੇਬਲ ਇੱਥੇ ਸਾਂਭੋ।",
  'print.carrier.pickFirstTap': "ਪਹਿਲਾਂ ਉੱਪਰ ਇੱਕ ਆਰਡਰ ਚੁਣੋ — ਫਿਰ ਇਹ ਬਟਨ ਕੈਰੀਅਰ ਲੇਬਲ ਉਸ ਆਰਡਰ ਵਿੱਚ ਸੇਵ ਕਰੇਗਾ।",
  "print.style.title": "ਦਸਤਾਵੇਜ਼ ਸ਼ੈਲੀ",
  "print.style.desc": "ਆਪਣੇ ਦਸਤਾਵੇਜ਼ਾਂ ਨੂੰ ਆਪਣਾ ਬਣਾਓ। ਇਹ ਚੋਣਾਂ ਤੁਹਾਡੇ ਇਨਵੌਇਸ, ਰਸੀਦ, ਪੈਕਿੰਗ ਸਲਿੱਪ, ਵਾਪਸੀ ਦਸਤਾਵੇਜ਼, ਉਤਪਾਦ ਸ਼ੀਟਾਂ, ਗਿਣਤੀ ਸ਼ੀਟਾਂ ਅਤੇ ਪਿਕ ਸੂਚੀਆਂ ਨੂੰ ਸਜਾਉਂਦੀਆਂ ਹਨ — ਅਤੇ ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਲਈ ਯਾਦ ਰੱਖੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।",
  "print.style.logoLabel": "ਤੁਹਾਡਾ ਲੋਗੋ",
  "print.style.logoOn": "ਤੁਹਾਡਾ ਲੋਗੋ ਤੁਹਾਡੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦੇ ਉੱਪਰ ਛਪਦਾ ਹੈ।",
  "print.style.logoOff": "ਅਜੇ ਕੋਈ ਲੋਗੋ ਨਹੀਂ। ਸੈਟਿੰਗਜ਼ ਵਿੱਚ ਇੱਕ ਸ਼ਾਮਲ ਕਰੋ ਅਤੇ ਇਹ ਤੁਹਾਡੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦੇ ਉੱਪਰ ਛਪੇਗਾ।",
  "print.style.color": "ਰੰਗ ਵਿੱਚ ਛਾਪੋ",
  "print.style.colorHint": "ਚਾਲੂ: ਤੁਹਾਡਾ ਲੋਗੋ, ਤਸਵੀਰਾਂ ਅਤੇ ਫਰੇਮ ਰੰਗ ਵਿੱਚ ਛਪਦੇ ਹਨ। ਬੰਦ: ਸਭ ਕੁਝ ਸਾਫ਼ ਕਾਲੇ-ਚਿੱਟੇ ਵਿੱਚ ਛਪਦਾ ਹੈ, ਸਿਆਹੀ ਬਚਦੀ ਹੈ।",
