  "print.style.imageSizeHint": "ਚੌੜਾਈ ਪੇਜ ਦੀ ਚੌੜਾਈ ਦਾ ਉਹ ਹਿੱਸਾ ਹੈ ਜੋ ਤਸਵੀਰ ਘੇਰਦੀ ਹੈ; ਲੰਬਾਈ ਛਪਾਈ ਦੀ ਸਭ ਤੋਂ ਵੱਧ ਉਚਾਈ ਹੈ। ਆਮ ਆਕਾਰ ਲਈ ਡੱਬਾ ਖਾਲੀ ਛੱਡੋ।",
  "print.printedAt": "{date} ਨੂੰ {time} ਵਜੇ ਛਾਪਿਆ ਗਿਆ",
  "print.style.previewText": "ਤੇਜ਼ ਭੂਰੀ ਲੂੰਬੜੀ ਆਲਸੀ ਕੁੱਤੇ ਉੱਤੋਂ ਛਾਲ ਮਾਰਦੀ ਹੈ। 1234567890",
  "training.lessons.owner-shipping-labels.step1": "ਪ੍ਰਿੰਟ ਸੈਂਟਰ ਵਿੱਚ ਦੋਵਾਂ ਯੋਜਨਾਵਾਂ ਵਿੱਚ ਸ਼ਿਪਿੰਗ ਲੇਬਲ ਸ਼ੈਲੀ ਹੈ: ਗਾਹਕ ਦਾ ਆਰਡਰ ਚੁਣੋ ਅਤੇ ਖਰੀਦਦਾਰ ਦੇ ਨਾਮ ਤੇ ਪਤੇ ਅਤੇ ਭੇਜਣ ਵਾਲੇ ਵਜੋਂ ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਵਾਲਾ 4×6 ਲੇਬਲ ਛਾਪੋ।",
  "training.lessons.owner-shipping-labels.step2": "ਇਹ ਲੇਬਲ ਹਰ ਗਾਹਕ ਦਸਤਾਵੇਜ਼ ਵਾਂਗ ਵ੍ਹਾਈਟ-ਲੇਬਲ ਹੈ: ਇਸ ’ਤੇ ਸਿਰਫ ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਦਾ ਨਾਮ ਹੁੰਦਾ ਹੈ — ਇਸ ਐਪ ਦਾ ਨਾਮ ਕਦੇ ਨਹੀਂ — ਤਾਂ ਜੋ ਤੁਹਾਡੀ ਦੁਕਾਨ ਤੋਂ ਆਇਆ ਪਾਰਸਲ ਤੁਹਾਡੀ ਹੀ ਦੁਕਾਨ ਤੋਂ ਆਇਆ ਲੱਗੇ।",
  "training.lessons.owner-shipping-labels.step3": "ਗਾਹਕ ਦਾ ਪਤਾ ਉਨ੍ਹਾਂ ਦੇ ਆਖਰੀ ਆਰਡਰ ਤੋਂ ਬਾਅਦ 90 ਦਿਨਾਂ ਤੱਕ ਉਨ੍ਹਾਂ ਦੇ ਆਰਡਰਾਂ ਨਾਲ ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਲੇਬਲ ਜਦੋਂ ਆਰਡਰ ਦਾ ਸੇਵ ਕੀਤਾ ਪਤਾ ਹੁੰਦਾ ਹੈ ਤਾਂ ਉਸ ਤੋਂ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ; ਇੱਕ ਵਾਰ ਦੇ ਲੇਬਲ ਲਈ ਪ੍ਰਿੰਟ ਸਮੇਂ ਟਾਈਪ ਕੀਤਾ ਪਤਾ ਵਾਪਸ ਸੇਵ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ। ਨਾਂ ਫਿਰ ਵੀ ਆਰਡਰ ਤੋਂ ਭਰਿਆ ਜਾਂਦਾ ਹੈ ਤਾਂ ਜੋ ਲੇਬਲ ਕਾਗਜ਼ਾਤ ਨਾਲ ਮੇਲ ਖਾਵੇ।",
  "training.lessons.owner-shipping-labels.step4": "ਇਹ ਲੇਬਲ ਹਰ ਲੇਬਲ ਵਾਂਗ ਉਹੀ ਚਾਰ ਕਨੈਕਸ਼ਨਾਂ ਰਾਹੀਂ ਛਪਦਾ ਹੈ — ਬਲੂਟੁੱਥ, ਵਾਈ-ਫਾਈ, ਈਥਰਨੈੱਟ ਅਤੇ USB — ਅਤੇ 4×6 ਥਰਮਲ ਪ੍ਰਿੰਟਰ ਇਸਦਾ ਮਿਆਰੀ ਆਕਾਰ ਹੈ।",
  "training.lessons.owner-shipping-labels.step5": "ਇਸ ਦੀ ਬਜਾਏ ਡਾਕ ਖਰਚ ਕੈਰੀਅਰ ਤੋਂ ਖਰੀਦਿਆ? ਇਸੇ ਭਾਗ ਵਿੱਚ ਤੁਸੀਂ ਕੈਰੀਅਰ ਦੀ ਲੇਬਲ ਫਾਈਲ — PDF, PNG ਜਾਂ JPG — ਅੱਪਲੋਡ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਇਹ ਆਰਡਰ ਉੱਤੇ ਹਮੇਸ਼ਾ ਸਾਂਭੀ ਰਹੇਗੀ: ਤੁਹਾਡਾ ਰਿਕਾਰਡ, ਜੇ ਕੁਝ ਹੋ ਜਾਵੇ ਤਾਂ ਹੱਥ ਵਿੱਚ। ਇਹ ਆਪਣੇ ਅਸਲ 4×6 ਆਕਾਰ ਵਿੱਚ ਛਪਦੀ ਹੈ। ਐਪ ਕਦੇ ਡਾਕ ਖਰਚ ਨਹੀਂ ਵੇਚਦਾ, ਇਸ ਲਈ ਕੈਰੀਅਰ ਦੀ ਕੀਮਤ ਹੀ ਇੱਕੋ ਕੀਮਤ ਹੈ — ਅਤੇ ਹਮੇਸ਼ਾ ਸਹੀ ਕੀਮਤ।",
  "training.lessons.owner-shipping-labels.title": "ਗਾਹਕ ਆਰਡਰਾਂ ਲਈ ਸ਼ਿਪਿੰਗ ਲੇਬਲ",
  "training.lessons.print-shipping-label.step1": "ਜਦੋਂ ਆਰਡਰ ਭੇਜਣ ਲਈ ਤਿਆਰ ਹੋਵੇ, ਪ੍ਰਿੰਟ ਸੈਂਟਰ ਖੋਲ੍ਹੋ, ਸ਼ਿਪਿੰਗ ਲੇਬਲ ਸ਼ੈਲੀ ਚੁਣੋ ਅਤੇ ਫਿਰ ਗਾਹਕ ਦਾ ਆਰਡਰ ਚੁਣੋ। ਖਰੀਦਦਾਰ ਦਾ ਨਾਮ ਆਰਡਰ ਤੋਂ ਭਰਿਆ ਜਾਂਦਾ ਹੈ।",
  "training.lessons.print-shipping-label.step2": "ਉਹ ਪਤਾ ਜਾਂਚੋ ਜਿੱਥੇ ਪਾਰਸਲ ਜਾ ਰਿਹਾ ਹੈ। ਜਦੋਂ ਆਰਡਰ ਵਿੱਚ ਗਾਹਕ ਦਾ ਪਤਾ ਹੁੰਦਾ ਹੈ — ਉਨ੍ਹਾਂ ਦੇ ਆਖਰੀ ਆਰਡਰ ਤੋਂ ਬਾਅਦ 90 ਦਿਨਾਂ ਤੱਕ ਰੱਖਿਆ ਗਿਆ — ਤਾਂ ਇਹ ਤੁਹਾਡੇ ਲਈ ਭਰਿਆ ਜਾਂਦਾ ਹੈ; ਪ੍ਰਿੰਟ ਸਮੇਂ ਤੁਸੀਂ ਜੋ ਪਤਾ ਟਾਈਪ ਕਰਦੇ ਹੋ ਉਹ ਵਾਪਸ ਸੇਵ ਨਹੀਂ ਹੁੰਦਾ, ਇਸ ਲਈ ਪ੍ਰਿੰਟ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਪੋਸਟਕੋਡ ਅਤੇ ਆਖਰੀ ਲਾਈਨ ਧਿਆਨ ਨਾਲ ਜਾਂਚੋ।",
  "training.lessons.print-shipping-label.step3": "ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਦਾ ਨਾਮ ਭੇਜਣ ਵਾਲੇ ਵਜੋਂ ਉੱਪਰ ਛਪਦਾ ਹੈ। ਜੇ ਤੁਹਾਡਾ ਪਤਾ ਵੀ ਲੇਬਲ ’ਤੇ ਚਾਹੀਦਾ ਹੈ, ਤਾਂ ਇਸਨੂੰ ਭੇਜਣ ਵਾਲੇ ਦੇ ਪਤੇ ਵਾਲੇ ਖਾਨੇ ਵਿੱਚ ਲਿਖੋ; ਜੇ ਨਹੀਂ ਦਿਖਾਉਣਾ ਤਾਂ ਖਾਲੀ ਛੱਡੋ।",
  "training.lessons.print-shipping-label.step4": "4×6 ਲੇਬਲ ’ਤੇ ਛਾਪੋ — ਥਰਮਲ ਲੇਬਲ ਪ੍ਰਿੰਟਰ ਆਮ ਚੋਣ ਹੈ — ਜਾਂ ਬ੍ਰਾਊਜ਼ਰ ਦੇ ਪ੍ਰਿੰਟ ਬਟਨ ਨਾਲ ਕਿਸੇ ਵੀ ਪ੍ਰਿੰਟਰ ’ਤੇ। ਲੇਬਲ ਨੂੰ ਪਾਰਸਲ ’ਤੇ ਸਮਤਲ ਚਿਪਕਾਓ, ਜਿੱਥੇ ਇਹ ਕਿਨਾਰੇ ’ਤੇ ਨਾ ਮੁੜੇ।",
  "training.lessons.print-shipping-label.step5": "ਜੇ ਡਾਕ ਖਰਚ ਕੈਰੀਅਰ ਤੋਂ ਖਰੀਦਿਆ ਗਿਆ ਸੀ, ਤਾਂ ਇਸ ਦੀ ਬਜਾਏ ਉਨ੍ਹਾਂ ਦੀ ਲੇਬਲ ਫਾਈਲ ਆਰਡਰ ਉੱਤੇ ਸਾਂਭੋ: ਤੁਹਾਡੇ ਕੈਰੀਅਰ ਦਾ ਲੇਬਲ ਭਾਗ ਵਿੱਚ ਕੈਰੀਅਰ ਵੱਲੋਂ ਦਿੱਤੀ PDF, PNG ਜਾਂ JPG ਅੱਪਲੋਡ ਕਰੋ। ਇਹ ਤੁਹਾਡੇ ਰਿਕਾਰਡ ਵਜੋਂ ਆਰਡਰ ਉੱਤੇ ਰਹਿੰਦੀ ਹੈ ਅਤੇ ਆਪਣੇ ਅਸਲ 4×6 ਆਕਾਰ ਵਿੱਚ ਛਪਦੀ ਹੈ — ਅਤੇ ਜਦੋਂ ਤੁਸੀਂ ਇਸ ਨੂੰ ਵਰਤਣਾ ਚਾਹੋ ਤਾਂ ਐਪ ਦਾ ਆਪਣਾ ਪਤਾ ਲੇਬਲ ਹਮੇਸ਼ਾ ਉੱਥੇ ਹੁੰਦਾ ਹੈ।",
  "training.lessons.print-shipping-label.title": "ਸ਼ਿਪਿੰਗ ਲੇਬਲ ਛਾਪੋ",
