  "apiErrors.alreadyCompleted.trainingAlreadyFinishedThere": "ਉਹ ਸਿਖਲਾਈ ਪਹਿਲਾਂ ਹੀ ਖਤਮ ਹੋ ਚੁੱਕੀ ਹੈ — ਚੇਤਾਵਨੀ ਦੇਣ ਲਈ ਕੁਝ ਨਹੀਂ ਹੈ।",
