  "apiErrors.alreadySubscribed": "ਇਸ ਕਾਰਜਸਥਾਨ ਦੀ ਪਹਿਲਾਂ ਹੀ ਮੈਂਬਰਸ਼ਿਪ ਹੈ। ਯੋਜਨਾ ਬਦਲਾਅ ਮੌਜੂਦਾ ਮੈਂਬਰਸ਼ਿਪ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਨ।",
  "apiErrors.authNotConfigured": "ਸੈਸ਼ਨ ਅਜੇ ਕੌਂਫਿਗਰ ਨਹੀਂ ਹਨ (SESSION_SECRET ਸੈੱਟ ਨਹੀਂ ਹੈ)।",
  "apiErrors.backupAlreadySet": "ਉਹ ਪਤਾ ਪਹਿਲਾਂ ਹੀ ਤੁਹਾਡਾ ਤਸਦੀਕ ਕੀਤਾ ਬੈਕਅੱਪ ਈਮੇਲ ਹੈ।",
  "apiErrors.backupSameAsAccount": "ਤੁਹਾਡਾ ਬੈਕਅੱਪ ਈਮੇਲ ਤੁਹਾਡੇ ਖਾਤਾ ਈਮੇਲ ਤੋਂ ਵੱਖਰਾ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ — ਇਹ ਉਦੋਂ ਦੀ ਵਾਧੂ ਕੁੰਜੀ ਹੈ ਜਦੋਂ ਇਹ ਈਮੇਲ ਪਹੁੰਚ ਤੋਂ ਬਾਹਰ ਹੋਵੇ।",
