  "apiErrors.subscriptionUnverified.stripeSubscriptionVerify": "ਤਸਦੀਕ ਕਰਨ ਲਈ ਕੋਈ Stripe ਮੈਂਬਰਸ਼ਿਪ ਨਹੀਂ ਹੈ।",
