  "apiErrors.wipeJobNotConfigured": "ਵਾਈਪ ਸਵੀਪ ਕੌਂਫਿਗਰ ਨਹੀਂ ਹੈ।",
  "settings.personal.subtitle": "ਤੁਹਾਡਾ ਆਪਣਾ ਖਾਤਾ, ਸੁਰੱਖਿਆ ਅਤੇ ਪਸੰਦਾਂ। ਕਾਰੋਬਾਰ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਮਾਲਕ ਕੋਲ ਰਹਿੰਦੀਆਂ ਹਨ।",
  "staffLib.area.settingsAccess": "ਸੈਟਿੰਗਾਂ ਤੱਕ ਪਹੁੰਚ",
