  "apiErrors.returnsCompleteReserved": "ਸਿਰਫ਼ ਮਾਲਕ, ਜਾਂ ਉਹ ਟੀਮ ਮੈਂਬਰ ਜਿਸ ਨੂੰ ਮਾਲਕ ਨੇ ਰਿਫੰਡ ਅਤੇ ਐਕਸਚੇਂਜ ਪੂਰੇ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਦਿੱਤੀ ਹੋਵੇ, ਕਿਸੇ ਰਿਟਰਨ ਨੂੰ ਮਨਜ਼ੂਰੀ ਦੇ ਕੇ ਪੂਰਾ ਕਰ ਸਕਦਾ ਹੈ।",
  "staffLib.perm.productsCreate": "ਨਵੇਂ ਉਤਪਾਦ ਸ਼ਾਮਲ ਕਰੋ",
  "staffLib.area.productsAccess": "ਉਤਪਾਦ ਸ਼ਾਮਲ ਕਰਨਾ",
  "staff.memberDialog.productsAccessHint": "ਇਸ ਨਿਸ਼ਾਨ ਨਾਲ, ਇਹ ਵਿਅਕਤੀ «ਨਵਾਂ ਉਤਪਾਦ» ਬਟਨ ਵੇਖਦਾ ਹੈ ਅਤੇ ਕੈਟਾਲੋਗ ਵਿੱਚ ਉਤਪਾਦ ਸ਼ਾਮਲ ਕਰ ਸਕਦਾ ਹੈ। ਇਸ ਤੋਂ ਬਿਨਾਂ, ਬਟਨ ਉਸਨੂੰ ਨਹੀਂ ਦਿਸਦੇ।",
  "productForm.readIsbnTitle": "ਛਪਿਆ ISBN ਪੜ੍ਹੋ",
  "productForm.readIsbnHint": "ਕੈਮਰਾ ਕਿਤਾਬ ’ਤੇ ਛਪੇ ISBN ਵੱਲ ਕਰੋ ਅਤੇ ਫਿਰ «ਨੰਬਰ ਪੜ੍ਹੋ» ਦਬਾਓ। ਜੇ ਬਾਰਕੋਡ ਪੜ੍ਹਿਆ ਜਾ ਸਕੇ ਤਾਂ ਉਹ ਵੀ ਨੰਬਰ ਭਰ ਦਿੰਦਾ ਹੈ।",
  "productForm.readIsbnButton": "ਨੰਬਰ ਪੜ੍ਹੋ",
