  "staffLib.perm.locationsCreate": "ਨਵੀਆਂ ਥਾਵਾਂ ਸ਼ਾਮਲ ਕਰੋ",
  "staffLib.area.locationsAccess": "ਥਾਵਾਂ ਸ਼ਾਮਲ ਕਰਨਾ",
  "staff.memberDialog.locationsAccessHint": "ਇਸ ਨਿਸ਼ਾਨ ਨਾਲ, ਇਹ ਵਿਅਕਤੀ ਨਵੀਆਂ ਥਾਵਾਂ ਸ਼ਾਮਲ ਕਰ ਸਕਦਾ ਹੈ। ਇਸ ਤੋਂ ਬਿਨਾਂ, ਥਾਂ ਸਿਰਫ਼ ਮਾਲਕ ਸ਼ਾਮਲ ਕਰ ਸਕਦਾ ਹੈ, ਅਤੇ ਸ਼ਾਮਲ ਕਰਨ ਵਾਲੇ ਬਟਨ ਉਸਨੂੰ ਨਹੀਂ ਦਿਸਦੇ।",
  "apiErrors.locationsCreateReserved": "ਸਿਰਫ਼ ਮਾਲਕ, ਜਾਂ ਟੀਮ ਦਾ ਉਹ ਮੈਂਬਰ ਜਿਸਨੂੰ ਮਾਲਕ ਨੇ ਥਾਵਾਂ ਸ਼ਾਮਲ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਦਿੱਤੀ ਹੋਵੇ, ਥਾਂ ਸ਼ਾਮਲ ਕਰ ਸਕਦਾ ਹੈ।",
  "settings.policies.title": "ਤੁਹਾਡੇ ਸਟੋਰ ਦੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ",
  "settings.policies.ownerDescription": "ਤੁਹਾਡਾ ਸਟੋਰ, ਤੁਹਾਡੇ ਨਿਯਮ। ਆਪਣੇ ਸਟੋਰ ਦੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਆਪਣੀਆਂ ਨਿਯਮ ਤੇ ਸ਼ਰਤਾਂ ਇੱਥੇ ਲਿਖੋ — ਉਹਨਾਂ ਨੂੰ ਲਿਖੋ, ਜਾਂ ਫਾਈਲ ਅੱਪਲੋਡ ਕਰੋ। ਟੀਮ ਦਾ ਹਰ ਨਵਾਂ ਮੈਂਬਰ ਸ਼ੁਰੂ ਕਰਨ ਵੇਲੇ ਉਹਨਾਂ ਨੂੰ ਇੱਕ ਵਾਰ ਵੇਖਦਾ ਹੈ, ਅਤੇ ਤੁਹਾਡੀ ਸਾਰੀ ਟੀਮ ਉਹਨਾਂ ਨੂੰ ਇੱਥੇ ਕਿਸੇ ਵੀ ਸਮੇਂ ਪੜ੍ਹ ਸਕਦੀ ਹੈ। ਉਹਨਾਂ ਨੂੰ ਸਿਰਫ਼ ਤੁਸੀਂ ਹੀ ਬਦਲ ਸਕਦੇ ਹੋ।",
  "settings.policies.memberDescription": "ਤੁਹਾਡੇ ਸਟੋਰ ਦੀਆਂ ਆਪਣੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ, ਮਾਲਕ ਦੁਆਰਾ ਲਿਖੀਆਂ। ਉਹਨਾਂ ਨੂੰ ਸਿਰਫ਼ ਮਾਲਕ ਹੀ ਬਦਲ ਸਕਦਾ ਹੈ।",
  "settings.policies.storePolicies": "ਸਟੋਰ ਨੀਤੀਆਂ",
  "settings.policies.termsConditions": "ਨਿਯਮ ਅਤੇ ਸ਼ਰਤਾਂ",
