  "settings.policies.orWrite": "ਜਾਂ ਇਸ ਦੀ ਬਜਾਏ ਇੱਥੇ ਲਿਖੋ:",
  "settings.platformPolicies.title": "Luminous StockHaven ਨੀਤੀਆਂ",
  "settings.platformPolicies.description": "ਐਪ ਦੀਆਂ ਆਪਣੀਆਂ ਸ਼ਰਤਾਂ ਅਤੇ ਨੀਤੀਆਂ। ਉਹ ਐਪ ਨਾਲ ਹੀ ਰਹਿੰਦੀਆਂ ਹਨ, ਅਤੇ ਟੀਮ ਵਿੱਚ ਹਰ ਕੋਈ ਉਹਨਾਂ ਨੂੰ ਇੱਥੇ ਪੜ੍ਹ ਸਕਦਾ ਹੈ।",
  "staffWelcome.policiesIntro": "ਤੁਹਾਡੇ ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ: ਤੁਹਾਡੇ ਸਟੋਰ ਦੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ, ਮਾਲਕ ਦੁਆਰਾ ਲਿਖੀਆਂ।",
  "plansLib.includes.storePolicies": "ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਤੁਹਾਡੇ ਸਟੋਰ ਦੀਆਂ ਆਪਣੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ, ਤੁਹਾਡੀ ਸਾਰੀ ਟੀਮ ਦੇ ਪੜ੍ਹਨ ਲਈ",
  "apiErrors.businessPoliciesOwnerOnly": "ਇਸ ਸਟੋਰ ਦੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ ਸਿਰਫ਼ ਮਾਲਕ ਹੀ ਬਦਲ ਸਕਦਾ ਹੈ।",
  "apiErrors.policyFileInvalid": "25 MB ਤੋਂ ਛੋਟੀ PDF, ਟੈਕਸਟ, Word ਜਾਂ OpenDocument ਫਾਈਲ ਭੇਜੋ।",
  "apiErrors.policyTextTooLong": "ਉਹ ਦਸਤਾਵੇਜ਼ ਇੱਥੇ ਲਿਖਣ ਲਈ ਬਹੁਤ ਲੰਬਾ ਹੈ। ਇਸ ਦੀ ਬਜਾਏ ਤੁਸੀਂ ਉਸਨੂੰ ਫਾਈਲ ਵਜੋਂ ਅੱਪਲੋਡ ਕਰ ਸਕਦੇ ਹੋ।",
  "training.lessons.owner-store-policies.title": "ਤੁਹਾਡੇ ਸਟੋਰ ਦੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ",
  "training.lessons.owner-store-policies.step1": "ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ ਅਤੇ ਸਟੋਰ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ ਵਾਲਾ ਕਾਰਡ ਲੱਭੋ। ਇਸ ਵਿੱਚ ਦੋ ਦਸਤਾਵੇਜ਼ ਹਨ: ਤੁਹਾਡੇ ਸਟੋਰ ਦੀਆਂ ਨੀਤੀਆਂ — ਤੁਹਾਡੇ ਸਟੋਰ ਲਈ ਘਰ ਦੇ ਨਿਯਮ — ਅਤੇ ਤੁਹਾਡੀਆਂ ਨਿਯਮ ਅਤੇ ਸ਼ਰਤਾਂ।",
  "training.lessons.owner-store-policies.step2": "ਹਰ ਦਸਤਾਵੇਜ਼ ਉੱਥੇ ਹੀ ਲਿਖਿਆ ਜਾ ਸਕਦਾ ਹੈ, ਜਾਂ ਫਾਈਲ ਵਜੋਂ ਅੱਪਲੋਡ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ (PDF, ਟੈਕਸਟ, Word ਜਾਂ OpenDocument, 25 MB ਤੱਕ)। ਇੱਕ ਜਾਂ ਦੂਜਾ: ਲਿਖਤ ਸੰਭਾਲਣ ਨਾਲ ਫਾਈਲ ਬਦਲ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਫਾਈਲ ਅੱਪਲੋਡ ਕਰਨ ਨਾਲ ਲਿਖਤ ਬਦਲ ਜਾਂਦੀ ਹੈ। ਦਸਤਾਵੇਜ਼ ਹਟਾਉਣ ਨਾਲ ਉਹ ਸਾਫ਼ ਹੋ ਜਾਂਦਾ ਹੈ।",
  "training.lessons.owner-store-policies.step3": "ਤੁਹਾਡੀ ਟੀਮ ਦੋਵੇਂ ਦਸਤਾਵੇਜ਼ ਇੱਕ ਵਾਰ ਵੇਖਦੀ ਹੈ, ਉਹਨਾਂ ਦੀ ਪਹਿਲੀ ਸ਼ੁਰੂਆਤ ਵੇਲੇ ਉਹਨਾਂ ਦੇ ਸਵਾਗਤ ਪੰਨੇ ’ਤੇ, ਅਤੇ ਉਹਨਾਂ ਨੂੰ ਕਿਸੇ ਵੀ ਸਮੇਂ ਆਪਣੀਆਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਪੜ੍ਹ ਸਕਦੀ ਹੈ। ਤੁਹਾਡੀ ਟੀਮ ਲਈ ਉਹ ਸਿਰਫ਼ ਪੜ੍ਹਨ ਲਈ ਹਨ — ਉਹਨਾਂ ਨੂੰ ਸਿਰਫ਼ ਤੁਸੀਂ ਹੀ ਲਿਖ ਜਾਂ ਬਦਲ ਸਕਦੇ ਹੋ।",
  "training.lessons.owner-store-policies.step4": "ਹਰ ਕਾਰੋਬਾਰ ਆਪਣੇ ਦਸਤਾਵੇਜ਼ ਆਪਣੇ ਕੋਲ ਰੱਖਦਾ ਹੈ: ਤੁਸੀਂ ਇੱਥੇ ਜੋ ਲਿਖਦੇ ਹੋ ਉਹ ਸਿਰਫ਼ ਇਸ ਸਟੋਰ ਦਾ ਹੈ ਅਤੇ ਕਦੇ ਕਿਸੇ ਹੋਰ ਕਾਰੋਬਾਰ ਵਿੱਚ ਨਹੀਂ ਦਿਸਦਾ। Luminous StockHaven ਦੀਆਂ ਆਪਣੀਆਂ ਸ਼ਰਤਾਂ ਅਤੇ ਨੀਤੀਆਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਤੁਹਾਡੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦੇ ਨਾਲ ਰਹਿੰਦੀਆਂ ਹਨ, ਅਤੇ ਉਹਨਾਂ ਨੂੰ ਵੀ ਹਰ ਕੋਈ ਪੜ੍ਹ ਸਕਦਾ ਹੈ।",
  "training.lessons.welcome-basics.step5": "ਤੁਹਾਡੇ ਸਟੋਰ ਦੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ ਤੁਹਾਡੇ ਸਵਾਗਤ ਪੰਨੇ ’ਤੇ ਇੱਕ ਵਾਰ ਵਿਖਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ, ਅਤੇ ਉਹ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਰਹਿੰਦੀਆਂ ਹਨ, ਜਿੱਥੇ ਤੁਸੀਂ ਉਹਨਾਂ ਨੂੰ ਕਿਸੇ ਵੀ ਸਮੇਂ ਪੜ੍ਹ ਸਕਦੇ ਹੋ।",
  "apiErrors.policyDocNotFound": "ਉਹ ਦਸਤਾਵੇਜ਼ ਦੋਵਾਂ ਵਿੱਚੋਂ ਇੱਕ ਨਹੀਂ ਹੈ।",
  "apiErrors.policyFileNotFound": "ਉਸ ਦਸਤਾਵੇਜ਼ ਲਈ ਕੋਈ ਫਾਈਲ ਸੰਭਾਲੀ ਨਹੀਂ ਗਈ ਹੈ।",
