  "training.policy.sectionHelp": "ਤੁਹਾਡੇ ਮਾਲਕ ਨੇ ਤੁਹਾਡੇ ਸਟੋਰ ਲਈ ਇਹ ਦਸਤਾਵੇਜ਼ ਲਿਖੇ ਹਨ। ਹਰ ਇੱਕ ਨੂੰ ਪੜ੍ਹੋ, ਫਿਰ ਆਪਣੇ ਮਾਲਕ ਦੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਜਵਾਬ ਦਿਓ।",
  "training.policy.sectionTitle": "ਤੁਹਾਡੇ ਸਟੋਰ ਦੀਆਂ ਨੀਤੀਆਂ ਅਤੇ ਸ਼ਰਤਾਂ",
  "training.policy.sentBack": "ਮਾਲਕ ਨੇ ਇਹ ਸਿਖਲਾਈ ਵਾਪਸ ਭੇਜ ਦਿੱਤੀ ਹੈ — ਕਿਰਪਾ ਕਰਕੇ ਇਸਨੂੰ ਦੁਬਾਰਾ ਲਓ।",
