  "training.quiz.belongs": "ਇਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕਿਹੜਾ ਇਹ ਪਾਠ ਸਿਖਾਉਂਦਾ ਹੈ?",
  "training.quiz.failed": "ਤੁਹਾਨੂੰ {total} ਵਿੱਚੋਂ {correct} ਮਿਲੇ। ਕਦਮਾਂ ਨੂੰ ਦੁਬਾਰਾ ਵੇਖੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "training.quiz.intro": "ਇਹ ਪਾਠ ਪੂਰਾ ਕਰਨ ਲਈ ਹਰ ਪ੍ਰਸ਼ਨ ਦਾ ਸਹੀ ਜਵਾਬ ਦਿਓ। ਤੁਸੀਂ ਜਿੰਨੀ ਵਾਰ ਚਾਹੋ ਕੋਸ਼ਿਸ਼ ਕਰ ਸਕਦੇ ਹੋ।",
