  "apiErrors.trainingQuizRequired": "ਇਹ ਪਾਠ ਇੱਕ ਛੋਟੀ ਕੁਇਜ਼ ਨਾਲ ਖਤਮ ਹੁੰਦਾ ਹੈ — ਪਾਠ ਪੂਰਾ ਕਰਨ ਲਈ ਸਹੀ ਜਵਾਬ ਦਿਓ।",
