  "apiErrors.trainingRecordTeam": "ਟੀਮ ਰਿਕਾਰਡ ਮਾਲਕ ਅਤੇ ਮੈਨੇਜਰਾਂ ਲਈ ਹਨ।",
  "profile.title": "ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ ਫੋਟੋ",
  "profile.ownerDesc": "ਤੁਹਾਡੀ ਫੋਟੋ ਅਤੇ ਉਹ ਨਾਂ ਜਿਸ ਨਾਲ ਤੁਹਾਡੀ ਟੀਮ ਤੁਹਾਨੂੰ ਜਾਣਦੀ ਹੈ। ਤੁਹਾਡੀ ਆਪਣੀ ਫੋਟੋ ਤੁਰੰਤ ਦਿਖਾਈ ਦਿੰਦੀ ਹੈ — ਕਿਸੇ ਮਨਜ਼ੂਰੀ ਦੀ ਲੋੜ ਨਹੀਂ।",
  "profile.memberDesc": "ਮਾਲਕ ਦੇ ਮਨਜ਼ੂਰ ਕਰਨ ਤੋਂ ਬਾਅਦ ਤੁਹਾਡੀ ਫੋਟੋ ਤੁਹਾਡੇ ਨਾਂ ਦੇ ਨਾਲ ਦਿਖਾਈ ਦਿੰਦੀ ਹੈ। ਉਦੋਂ ਤੱਕ, ਸਿਰਫ਼ ਤੁਹਾਡੇ ਨਾਂ ਦੇ ਪਹਿਲੇ ਅੱਖਰ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ।",
  "profile.stateApproved": "ਇਹੀ ਫੋਟੋ ਤੁਹਾਡੀ ਟੀਮ ਵੇਖਦੀ ਹੈ।",
  "profile.stateNone": "ਤੁਸੀਂ ਅਜੇ ਤੱਕ ਕੋਈ ਫੋਟੋ ਨਹੀਂ ਜੋੜੀ।",
  "profile.statePending": "ਤੁਹਾਡੀ ਫੋਟੋ ਮਾਲਕ ਦੀ ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਕਰ ਰਹੀ ਹੈ। ਜਦੋਂ ਤੱਕ ਉਹ ਮਨਜ਼ੂਰ ਨਹੀਂ ਕਰਦੇ, ਇਹ ਕਿਧਰੇ ਵੀ ਨਹੀਂ ਦਿਖਾਈ ਦਿੰਦੀ।",
  "profile.stateChangePending": "ਤੁਹਾਡੀ ਨਵੀਂ ਫੋਟੋ ਮਾਲਕ ਦੀ ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਕਰ ਰਹੀ ਹੈ। ਉਦੋਂ ਤੱਕ ਤੁਹਾਡੀ ਮੌਜੂਦਾ ਫੋਟੋ ਉਵੇਂ ਹੀ ਰਹਿੰਦੀ ਹੈ।",
