  "profile.declinedFirst": "ਤੁਹਾਡੀ ਫੋਟੋ ਮਨਜ਼ੂਰ ਨਹੀਂ ਹੋਈ। ਕਿਰਪਾ ਕਰਕੇ ਕੋਈ ਹੋਰ ਫੋਟੋ ਚੁਣੋ।",
  "profile.declinedChange": "ਤੁਹਾਡੀ ਫੋਟੋ ਮਨਜ਼ੂਰ ਨਹੀਂ ਹੋਈ — ਪਰ ਤੁਹਾਡੀ ਦੂਜੀ ਫੋਟੋ ਅਜੇ ਵੀ ਹੈ। ਜੇ ਤੁਸੀਂ ਇਸਨੂੰ ਬਦਲਣਾ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ ਕੋਈ ਹੋਰ ਫੋਟੋ ਅਜ਼ਮਾਓ।",
