  "profile.toastOwnerLive": "ਤੁਹਾਡੀ ਫੋਟੋ ਲਾਈਵ ਹੈ।",
  "profile.toastSent": "ਮਨਜ਼ੂਰੀ ਲਈ ਮਾਲਕ ਕੋਲ ਭੇਜੀ ਗਈ।",
  "profile.toastFailed": "ਉਹ ਕੰਮ ਨਹੀਂ ਹੋਇਆ — ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
