  "profile.approvalsTitle": "ਤੁਹਾਡੀ ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਕਰਦੀਆਂ ਫੋਟੋਆਂ",
  "profile.approvalsDesc": "ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਮਨਜ਼ੂਰ ਨਹੀਂ ਕਰਦੇ, ਟੀਮ ਦੀ ਫੋਟੋ ਕਿਧਰੇ ਵੀ ਨਹੀਂ ਦਿਖਾਈ ਦਿੰਦੀ। ਜੇ ਤੁਸੀਂ ਮਨਜ਼ੂਰ ਨਹੀਂ ਕਰਦੇ, ਤਾਂ ਉਸ ਵਿਅਕਤੀ ਨੂੰ ਕੋਈ ਹੋਰ ਫੋਟੋ ਚੁਣਨ ਲਈ ਕਿਹਾ ਜਾਂਦਾ ਹੈ।",
  "profile.approve": "ਮਨਜ਼ੂਰ ਕਰੋ",
