  "payroll.dd.styleItalic": "ਤਿਰਛੀ",
  "payroll.dd.styleScript": "ਵਹਿੰਦੀ ਲਿਖਤ",
  "payroll.dd.styleSimple": "ਸਾਦਾ ਅਤੇ ਸਪਸ਼ਟ",
  "payroll.dd.viewForm": "ਦਸਤਖਤ ਕੀਤਾ ਫਾਰਮ ਦੇਖੋ",
  "payroll.profile.address": "ਘਰ ਦਾ ਪਤਾ",
  "payroll.profile.name": "ਪੂਰਾ ਨਾਂ",
  "payroll.profile.noAddress": "ਅਜੇ ਤੱਕ ਘਰ ਦਾ ਕੋਈ ਪਤਾ ਦਰਜ ਨਹੀਂ ਹੈ।",
  "payroll.profile.note": "ਇਹ ਵੇਰਵੇ ਤੁਹਾਡੇ ਤਨਖਾਹ ਅਤੇ ਟੈਕਸ ਫਾਰਮਾਂ ਲਈ ਵਰਤੇ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਸਿਰਫ਼ ਤੁਸੀਂ ਇਹਨਾਂ ਨੂੰ ਇੱਥੇ ਦੇਖ ਸਕਦੇ ਹੋ। ਜੇ ਕੁਝ ਬਦਲਣ ਦੀ ਲੋੜ ਹੋਵੇ, ਤਾਂ ਮਾਲਕ ਜਾਂ ਆਪਣੇ ਮੈਨੇਜਰ ਨੂੰ ਕਹੋ — ਉਹੀ ਇਹਨਾਂ ਨੂੰ ਅੱਪਡੇਟ ਕਰ ਸਕਦੇ ਹਨ।",
  "payroll.profile.title": "ਤੁਹਾਡੇ ਦਰਜ ਵੇਰਵੇ",
  "payroll.stubs.print": "ਛਾਪੋ / ਡਾਊਨਲੋਡ",
  "apiErrors.invalidValue.signYourForm": "ਆਪਣੇ ਸਿੱਧੀ ਜਮ੍ਹਾਂ ਫਾਰਮ ਉੱਤੇ ਦਸਤਖਤ ਕਰਨ ਲਈ ਆਪਣਾ ਨਾਂ ਲਿਖੋ।",
  "apiErrors.invalidValue.chooseSignatureStyle": "ਦਸਤਖਤ ਦੀ ਸ਼ੈਲੀ ਚੁਣੋ।",
  "apiErrors.invalidValue.noDdDetailsYet": "ਉਸ ਟੀਮ ਮੈਂਬਰ ਨੇ ਅਜੇ ਤੱਕ ਆਪਣੇ ਵੇਰਵੇ ਨਹੀਂ ਭੇਜੇ।",
  "training.lessons.owner-dd-setup.step5": "ਜੋ ਪਹੁੰਚਦਾ ਹੈ ਉਹ ਇੱਕ ਮੋਹਰਬੰਦ, ਦਸਤਖਤ ਕੀਤਾ ਫਾਰਮ ਹੈ: ਤਨਖਾਹ ਸੂਚੀ ਵਿੱਚ ਉਸ ਵਿਅਕਤੀ ਦੀ ਕਤਾਰ ਤੋਂ ਤੁਸੀਂ ਇਸਨੂੰ ਖੋਲ੍ਹ ਕੇ ਪੂਰੇ ਨੰਬਰ ਪੜ੍ਹ ਸਕਦੇ ਹੋ, ਛਾਪ ਸਕਦੇ ਹੋ ਜਾਂ ਇੱਕ ਕਾਪੀ ਸਾਂਭ ਸਕਦੇ ਹੋ — ਤੁਸੀਂ ਇਸਨੂੰ ਕਦੇ ਸੰਪਾਦਿਤ ਨਹੀਂ ਕਰ ਸਕਦੇ। ਜੇ ਕੋਈ ਨੰਬਰ ਗਲਤ ਲੱਗੇ, ਤਾਂ ਫਾਰਮ ਵਾਪਸ ਭੇਜੋ: ਉਹ ਵਿਅਕਤੀ ਖੁਦ ਇਸਨੂੰ ਸੁਧਾਰਦਾ ਹੈ ਅਤੇ ਦੁਬਾਰਾ ਦਸਤਖਤ ਕਰਦਾ ਹੈ, ਉਸਦਾ ਸੁਧਾਰਿਆ ਫਾਰਮ ਪੁਰਾਣੇ ਦੀ ਥਾਂ ਲੈ ਲੈਂਦਾ ਹੈ, ਅਤੇ ਪਿਛਲਾ ਫਾਰਮ ਆਪਣੀ ਬਦਲੀ ਦੀ ਤਾਰੀਖ ਨਾਲ ਰਿਕਾਰਡ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ।",
  "payroll.profile.ownerNote": "ਇਹ ਤੁਹਾਡੇ ਆਪਣੇ ਵੇਰਵੇ ਹਨ ਜੋ ਫਾਈਲ ਵਿੱਚ ਹਨ, ਤੁਹਾਡੇ ਖਾਤੇ ਤੋਂ। ਸਿਰਫ਼ ਤੁਸੀਂ ਹੀ ਇਹਨਾਂ ਨੂੰ ਇੱਥੇ ਦੇਖ ਸਕਦੇ ਹੋ — ਅਤੇ ਇਹ ਤੁਹਾਡੇ ਹੋਣ ਕਰਕੇ, ਬਦਲਣ ’ਤੇ ਤੁਸੀਂ ਇਹਨਾਂ ਨੂੰ ਇੱਥੇ ਹੀ ਅੱਪਡੇਟ ਕਰ ਸਕਦੇ ਹੋ।",
