  "apiErrors.forbidden.businessOwnerUpdateDetails": "ਸਿਰਫ਼ ਕਾਰੋਬਾਰ ਦਾ ਮਾਲਕ ਹੀ ਇਹ ਵੇਰਵੇ ਅੱਪਡੇਟ ਕਰ ਸਕਦਾ ਹੈ।",
