  "staffLib.perm.staffClockBoard": "ਘੜੀ ਬੋਰਡ ਅਤੇ ਛੁੱਟੇ ਹੋਏ ਕਲਾਕ-ਆਊਟ",
  "staffLib.perm.staffCallins": "ਕਾਲ-ਇਨ",
  "staffLib.area.clockAccess": "ਘੜੀ ਬੋਰਡ ਅਤੇ ਕਾਲ-ਇਨ",
  "staff.memberDialog.clockAccessHint": "ਸਿਰਫ਼ ਮੈਨੇਜਰਾਂ ਲਈ — ਦੋ ਵੱਖਰੇ ਨਿਸ਼ਾਨ। ਘੜੀ ਬੋਰਡ ਅਤੇ ਛੁੱਟੇ ਹੋਏ ਕਲਾਕ-ਆਊਟ ਇਸ ਮੈਨੇਜਰ ਨੂੰ ਟੀਮ ਦੀਆਂ ਘੜੀ ਐਂਟਰੀਆਂ ਦੇਖਣ ਅਤੇ ਸਟਾਫ਼ ਪੇਜ ਤੋਂ ਸਮਾਂ ਐਂਟਰੀਆਂ ਠੀਕ ਕਰਨ ਦਿੰਦਾ ਹੈ। ਕਾਲ-ਇਨ ਇਸ ਮੈਨੇਜਰ ਨੂੰ ਕਾਲ-ਇਨ ਵਿੰਡੋਜ਼ ਖੋਲ੍ਹਣ ਦਿੰਦਾ ਹੈ, ਕਿਸੇ ਨੂੰ ਉਦੋਂ ਕੰਮ ਕਰਨ ਦੇਣਾ ਜਦੋਂ ਉਸਦੀ ਸ਼ਿਫਟ ਤੈਅ ਨਾ ਹੋਵੇ। ਇਹ ਨਿਸ਼ਾਨ ਸਟਾਫ਼ ਲਈ ਕੁਝ ਨਹੀਂ ਕਰਦੇ।",
  "workforce.clockGate.closed": "ਇਸ ਵੇਲੇ ਤੁਹਾਡਾ ਕੰਮ ਤੈਅ ਨਹੀਂ ਹੈ, ਅਤੇ ਤੁਹਾਡੇ ਲਈ ਕੋਈ ਕਾਲ-ਇਨ ਵਿੰਡੋ ਖੁੱਲ੍ਹੀ ਨਹੀਂ ਹੈ।",
  "workforce.clockGate.closedNext": "ਇਸ ਵੇਲੇ ਤੁਹਾਡਾ ਕੰਮ ਤੈਅ ਨਹੀਂ ਹੈ, ਅਤੇ ਤੁਹਾਡੇ ਲਈ ਕੋਈ ਕਾਲ-ਇਨ ਵਿੰਡੋ ਖੁੱਲ੍ਹੀ ਨਹੀਂ ਹੈ। ਤੁਹਾਡੀ ਅਗਲੀ ਸ਼ਿਫਟ {when} ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ।",
