  "staff.callIn.desc": "ਕਿਸੇ ਦੀ ਸ਼ਿਫਟ ਤੈਅ ਨਾ ਹੋਵੇ ਤਾਂ ਉਸਨੂੰ ਬੁਲਾਓ, ਅਤੇ ਕਲਾਕ-ਆਊਟ ਭੁੱਲ ਜਾਵੇ ਤਾਂ ਸਮਾਂ ਐਂਟਰੀਆਂ ਠੀਕ ਕਰੋ। ਕਾਲ-ਇਨ ਵਿੰਡੋ ਉਦੋਂ ਤੱਕ ਖੁੱਲ੍ਹੀ ਰਹਿੰਦੀ ਹੈ ਜਦੋਂ ਤੱਕ ਉਹ ਵਿਅਕਤੀ ਕਲਾਕ ਆਊਟ ਨਾ ਕਰੇ।",
