  "apiErrors.clockAdmin.boardNotGranted": "ਸਿਰਫ਼ ਮਾਲਕ, ਜਾਂ ਉਹ ਮੈਨੇਜਰ ਜਿਸ ’ਤੇ ਮਾਲਕ ਨੇ ਘੜੀ ਬੋਰਡ ਅਤੇ ਛੁੱਟੇ ਹੋਏ ਕਲਾਕ-ਆਊਟ ਲਈ ਭਰੋਸਾ ਕੀਤਾ ਹੋਵੇ, ਇਹ ਕਰ ਸਕਦਾ ਹੈ।",
  "apiErrors.clockAdmin.ownerOnlyForManager": "ਮੈਨੇਜਰ ਦੀਆਂ ਕਾਲ-ਇਨ ਅਤੇ ਸਮਾਂ ਐਂਟਰੀਆਂ ਸਿਰਫ਼ ਮਾਲਕ ਹੀ ਸੰਭਾਲ ਸਕਦਾ ਹੈ।",
  "apiErrors.clockFix.outBeforeIn": "ਕਲਾਕ-ਆਊਟ ਦਾ ਸਮਾਂ ਕਲਾਕ-ਇਨ ਦੇ ਸਮੇਂ ਤੋਂ ਬਾਅਦ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "apiErrors.clockFix.breakOutside": "ਵਿਰਾਮਾਂ ਦੇ ਸਮੇਂ ਕਲਾਕ-ਇਨ ਅਤੇ ਕਲਾਕ-ਆਊਟ ਸਮਿਆਂ ਦੇ ਵਿਚਕਾਰ ਹੋਣੇ ਚਾਹੀਦੇ ਹਨ।",
  "apiErrors.clockFix.invalidTime": "ਹਰ ਸਮੇਂ ਨੂੰ ਵੈਧ ਤਾਰੀਖ਼ ਅਤੇ ਸਮੇਂ ਵਜੋਂ ਭੇਜੋ।",
  "apiErrors.notFound.timeEntryFound": "ਸਮਾਂ ਐਂਟਰੀ ਨਹੀਂ ਮਿਲੀ।",
  "training.lessons.mgr-clock-callin.title": "ਕਾਲ-ਇਨ ਅਤੇ ਘੜੀ ਸੋਧਾਂ",
  "training.lessons.mgr-clock-callin.step1": "ਮਾਲਕ ਮੈਨੇਜਰ ਨੂੰ ਦੋ ਵੱਖਰੇ ਨਿਸ਼ਾਨ ਦੇ ਸਕਦਾ ਹੈ। ਕਾਲ-ਇਨ ਨਾਲ, ਤੁਸੀਂ ਸਟਾਫ਼ ਮੈਂਬਰ ਲਈ ਕਾਲ-ਇਨ ਵਿੰਡੋ ਖੋਲ੍ਹ ਸਕਦੇ ਹੋ, ਅਤੇ ਘੜੀ ਬੋਰਡ ਅਤੇ ਛੁੱਟੇ ਹੋਏ ਕਲਾਕ-ਆਊਟ ਨਾਲ, ਤੁਸੀਂ ਟੀਮ ਦਾ ਘੜੀ ਬੋਰਡ ਦੇਖ ਸਕਦੇ ਹੋ ਅਤੇ ਸਟਾਫ਼ ਪੇਜ ਤੋਂ ਸਮਾਂ ਐਂਟਰੀਆਂ ਠੀਕ ਕਰ ਸਕਦੇ ਹੋ। ਹਰ ਨਿਸ਼ਾਨ ਆਪਣੇ ਆਪ ਕੰਮ ਕਰਦਾ ਹੈ — ਮੈਨੇਜਰ ਇੱਕ ਤੋਂ ਬਿਨਾਂ ਦੂਜਾ ਰੱਖ ਸਕਦਾ ਹੈ।",
  "training.lessons.mgr-clock-callin.step2": "ਕਾਲ-ਇਨ ਵਿੰਡੋ ਕਿਸੇ ਵਿਅਕਤੀ ਨੂੰ ਉਦੋਂ ਸਾਈਨ ਇਨ ਅਤੇ ਕਲਾਕ ਇਨ ਕਰਨ ਦਿੰਦੀ ਹੈ ਜਦੋਂ ਕੋਈ ਸ਼ਿਫਟ ਉਸਨੂੰ ਨਾ ਢੱਕਦੀ ਹੋਵੇ। ਇਸਨੂੰ ਸਟਾਫ਼ ਪੇਜ ’ਤੇ, ਕਾਲ-ਇਨ ਅਤੇ ਛੁੱਟੇ ਕਲਾਕ-ਆਊਟ ਕਾਰਡ ਤੋਂ ਖੋਲ੍ਹੋ।",
  "training.lessons.mgr-clock-callin.step3": "ਵਿੰਡੋ ਉਦੋਂ ਤੱਕ ਖੁੱਲ੍ਹੀ ਰਹਿੰਦੀ ਹੈ ਜਦੋਂ ਤੱਕ ਉਹ ਵਿਅਕਤੀ ਕਲਾਕ ਆਊਟ ਨਾ ਕਰੇ — ਫਿਰ ਸਾਈਨ-ਆਊਟ ਤੋਂ ਪਹਿਲਾਂ ਦੀ ਆਮ 10-ਮਿੰਟ ਦੀ ਛੋਟ ਆਉਂਦੀ ਹੈ — ਜਾਂ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਜਾਂ ਮਾਲਕ ਇਸਨੂੰ ਪਹਿਲਾਂ ਬੰਦ ਨਾ ਕਰੋ। ਕੁਝ ਵੀ ਇਸਨੂੰ ਆਪਣੇ ਆਪ ਬੰਦ ਨਹੀਂ ਕਰਦਾ।",
  "training.lessons.mgr-clock-callin.step4": "ਜਦੋਂ ਕੋਈ ਕਲਾਕ ਆਊਟ ਕਰਨਾ ਭੁੱਲ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਤੈਅ ਸ਼ਿਫਟ ਖ਼ਤਮ ਹੁੰਦੇ ਹੀ ਉਸਦੀ ਐਂਟਰੀ ਸਟਾਫ਼ ਪੇਜ ਅਤੇ ਪੇਰੋਲ ਵਿੱਚ ਚਿੰਨ੍ਹਿਤ ਹੋ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਤੁਹਾਨੂੰ ਅਤੇ ਮਾਲਕ ਨੂੰ ਸੂਚਨਾ ਮਿਲਦੀ ਹੈ। ਐਂਟਰੀ ਠੀਕ ਹੋਣ ਤੱਕ ਗਿਣਦੀ ਰਹਿੰਦੀ ਹੈ।",
  "training.lessons.mgr-clock-callin.step5": "ਸਟਾਫ਼ ਪੇਜ ਤੋਂ ਐਂਟਰੀ ਠੀਕ ਕਰੋ: ਕਲਾਕ-ਇਨ, ਕਲਾਕ-ਆਊਟ ਅਤੇ ਵਿਰਾਮਾਂ ਦੇ ਸਮੇਂ ਤੈਅ ਕਰੋ। ਮੈਨੇਜਰ ਸਿਰਫ਼ ਸਟਾਫ਼ ਦੀਆਂ ਐਂਟਰੀਆਂ ਠੀਕ ਕਰਦਾ ਹੈ — ਮੈਨੇਜਰ ਦੀਆਂ ਆਪਣੀਆਂ ਐਂਟਰੀਆਂ ਮਾਲਕ ਠੀਕ ਕਰਦਾ ਹੈ।",
  "staffLib.perm.staffDocuments": "ਸਟਾਫ਼ ਦਸਤਾਵੇਜ਼",
  "staffLib.area.documentsAccess": "ਸਟਾਫ਼ ਦਸਤਾਵੇਜ਼",
  "staff.memberDialog.documentsAccessHint": "ਸਿਰਫ਼ ਮੈਨੇਜਰਾਂ ਲਈ — ਇਸ ਟਿਕ ਨਾਲ, ਇਹ ਮੈਨੇਜਰ ਸਟਾਫ਼ ਮੈਂਬਰਾਂ ਦੀਆਂ ਦਸਤਾਵੇਜ਼ ਫ਼ਾਈਲਾਂ ਖੋਲ੍ਹ ਸਕਦਾ ਹੈ: ਹਰ ਵਿਅਕਤੀ ਲਈ ਰੱਖੇ ਕਾਗਜ਼ਾਤ, ਜਿਵੇਂ W-4 ਫਾਰਮ, ਨੌਕਰੀ ਦੀਆਂ ਅਰਜ਼ੀਆਂ ਅਤੇ ਪਛਾਣ ਪੱਤਰ ਦੀਆਂ ਕਾਪੀਆਂ। ਪਹਿਲਾਂ ਤੁਹਾਡੀ ਪੁਸ਼ਟੀ ਮੰਗੀ ਜਾਵੇਗੀ — ਇਨ੍ਹਾਂ ਫ਼ਾਈਲਾਂ ਵਿੱਚ ਸਮਾਜਿਕ ਸੁਰੱਖਿਆ ਨੰਬਰ ਅਤੇ ਜਨਮ ਤਾਰੀਖਾਂ ਹੁੰਦੀਆਂ ਹਨ। ਇਹ ਟਿਕ ਸਟਾਫ਼ ਲਈ ਕੁਝ ਨਹੀਂ ਕਰਦਾ।",
  "staff.documentsWarning.body": "ਇਹ ਵਿਅਕਤੀ ਤੁਹਾਡੇ ਸਟਾਫ਼ ਮੈਂਬਰਾਂ ਬਾਰੇ ਗੁਪਤ ਜਾਣਕਾਰੀ ਦੇਖ ਸਕੇਗਾ, ਜਿਸ ਵਿੱਚ ਸਮਾਜਿਕ ਸੁਰੱਖਿਆ ਨੰਬਰ ਅਤੇ ਜਨਮ ਤਾਰੀਖਾਂ ਸ਼ਾਮਲ ਹਨ।",
  "staff.documentsWarning.confirm": "ਹਾਂ, ਮੈਂ ਸਮਝਦਾ ਹਾਂ",
  "staff.documents.title": "ਸਟਾਫ਼ ਦਸਤਾਵੇਜ਼",
  "staff.documents.desc": "ਉਹ ਕਾਗਜ਼ਾਤ ਜੋ ਤੁਸੀਂ ਹਰ ਵਿਅਕਤੀ ਲਈ ਰੱਖਦੇ ਹੋ — W-4 ਫਾਰਮ, ਨੌਕਰੀ ਦੀਆਂ ਅਰਜ਼ੀਆਂ, ਟੈਕਸ ਫਾਰਮ, ਪਛਾਣ ਪੱਤਰ ਦੀਆਂ ਕਾਪੀਆਂ। ਸਿਰਫ਼ ਤੁਸੀਂ, ਅਤੇ ਉਹ ਮੈਨੇਜਰ ਜਿਸਨੂੰ ਤੁਸੀਂ ਸਟਾਫ਼ ਦਸਤਾਵੇਜ਼ ਟਿਕ ਦਿੰਦੇ ਹੋ, ਇਹ ਫ਼ਾਈਲਾਂ ਖੋਲ੍ਹ ਸਕਦੇ ਹੋ।",
