  "staff.documents.fileInvalid": "25 MB ਤੋਂ ਛੋਟੀ PDF, ਟੈਕਸਟ, Word, OpenDocument ਜਾਂ ਤਸਵੀਰ ਫ਼ਾਈਲ ਚੁਣੋ।",
  "staff.documents.mineTitle": "ਮੇਰੇ ਦਸਤਾਵੇਜ਼",
  "staff.documents.mineDesc": "ਉਹ ਕਾਗਜ਼ਾਤ ਜੋ ਤੁਹਾਡਾ ਮਾਲਕ ਤੁਹਾਡੇ ਲਈ ਫ਼ਾਈਲ ਵਿੱਚ ਰੱਖਦਾ ਹੈ — W-4 ਫਾਰਮ, ਤੁਹਾਡੀ ਨੌਕਰੀ ਦੀ ਅਰਜ਼ੀ, ਟੈਕਸ ਫਾਰਮ, ਪਛਾਣ ਪੱਤਰ ਦੀਆਂ ਕਾਪੀਆਂ। ਇਹ ਤੁਹਾਡੀ ਆਪਣੀ ਫ਼ਾਈਲ ਹੈ: ਤੁਸੀਂ ਇਸ ਵਿੱਚੋਂ ਕੁਝ ਵੀ ਖੋਲ੍ਹ, ਡਾਊਨਲੋਡ ਅਤੇ ਛਾਪ ਸਕਦੇ ਹੋ, ਪਰ ਇੱਥੇ ਕੁਝ ਬਦਲਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ।",
  "staff.documents.mineEmpty": "ਤੁਹਾਡੇ ਲਈ ਅਜੇ ਫ਼ਾਈਲ ਵਿੱਚ ਕੁਝ ਨਹੀਂ ਹੈ।",
