  "restaurant.subtitle": "ਕਿਸੇ ਪਕਵਾਨ ਨੂੰ ਉਸ ਨਾਲ ਜੋੜੋ ਜੋ ਤੁਸੀਂ ਵੇਚਦੇ ਹੋ, ਅਤੇ ਉਸ ਦੀਆਂ ਸਮੱਗਰੀਆਂ ਆਪਣੀ ਦੇਖਭਾਲ ਆਪ ਕਰਦੀਆਂ ਹਨ — ਹਰ ਵਿਕਰੀ ਉਹਨਾਂ ਨੂੰ ਸ਼ੈਲਫ ਤੋਂ ਘਟਾਉਂਦੀ ਹੈ, ਅਤੇ ਪਕਵਾਨ ਪੰਨਾ ਦਿਖਾਉਂਦਾ ਹੈ ਕਿ ਇਸ ਦੀ ਅਸਲ ਲਾਗਤ ਕੀ ਹੈ।",
