  "restaurant.emptyBody": "ਆਪਣੀ ਪਹਿਲੀ ਵਿਧੀ ਲਿਖੋ — ਇੱਕ ਸਾਸ, ਇੱਕ ਪਕਵਾਨ, ਸਟਾਕ ਵਿੱਚ ਮੌਜੂਦ ਚੀਜ਼ਾਂ ਤੋਂ ਬਣਾਈ ਕੋਈ ਵੀ ਚੀਜ਼ — ਅਤੇ ਜਦੋਂ ਤੁਸੀਂ ਇਸ ਨੂੰ ਵੇਚਣ ਲਈ ਤਿਆਰ ਹੋਵੋ ਤਾਂ ਇਸ ਨੂੰ ਕਿਸੇ ਉਤਪਾਦ ਨਾਲ ਜੋੜੋ।",
