  "apiErrors.recipeAlreadyActive": "ਉਸ ਪਕਵਾਨ ਦੀ ਪਹਿਲਾਂ ਤੋਂ ਇੱਕ ਸਰਗਰਮ ਵਿਧੀ ਹੈ। ਪਹਿਲਾਂ ਦੂਜੀ ਵਿਧੀ ਨੂੰ ਵਾਪਸ ਡਰਾਫਟ 'ਤੇ ਸੈੱਟ ਕਰੋ।",
