  "ops.invoices.subtitle": "ਹਰ ਸਪਲਾਇਰ ਨੇ ਕੀ ਬਿੱਲ ਕੀਤਾ, ਉਸ ਦੇ ਖਰੀਦ ਆਰਡਰ ਨਾਲ ਤਿੰਨ ਤਰੀਕਿਆਂ ਨਾਲ ਜਾਂਚਿਆ: ਆਰਡਰ ਕੀਤਾ, ਪ੍ਰਾਪਤ ਕੀਤਾ ਅਤੇ ਇਨਵੌਇਸ ਕੀਤਾ। ਜਦੋਂ ਕੋਈ ਬਿੱਲ ਕੀਤੀ ਕੀਮਤ ਬਦਲਦੀ ਹੈ, ਇੱਥੇ ਇੱਕ ਕੀਮਤ ਚੇਤਾਵਨੀ ਖੁੱਲ੍ਹਦੀ ਹੈ।",
