  "variance.title": "ਫਰਕ",
  "variance.subtitle": "ਪ੍ਰਤੀ ਉਤਪਾਦ: ਵਿਧੀਆਂ ਕਹਿੰਦੀਆਂ ਹਨ ਕਿ ਸ਼ੈਲਫ਼ ਤੋਂ ਕੀ ਜਾਣਾ ਚਾਹੀਦਾ ਸੀ, ਸਟਾਫ ਖਾਣੇ, ਬਰਬਾਦੀ ਅਤੇ ਹੋਰ ਸਭ ਕੁਝ ਜੋ ਗਿਆ, ਉਸ ਦੇ ਨਾਲ। ਜੋ ਬਿਨਾਂ ਸਪਸ਼ਟੀਕਰਨ ਬਚਦਾ ਹੈ, ਉਹੀ ਪਾੜਾ ਹੈ ਜਿਸ ਨੂੰ ਜਾ ਕੇ ਸਮਝਾਉਣਾ ਹੈ।",
