  "variance.emptyBody": "ਕੋਈ ਪਕਵਾਨ ਵੇਚੋ, ਬਰਬਾਦੀ ਦਰਜ ਕਰੋ ਜਾਂ ਸਟਾਫ ਖਾਣਾ ਦਰਜ ਕਰੋ, ਅਤੇ ਇਹ ਪੰਨਾ ਤੁਲਨਾ ਕਰਦਾ ਹੈ ਕਿ ਵਿਧੀਆਂ ਨੇ ਕੀ ਉਮੀਦ ਕੀਤੀ ਸੀ ਅਤੇ ਅਸਲ ਵਿੱਚ ਕੀ ਗਿਆ।",
