  "exportsLib.restaurantLedger.title": "ਰੈਸਟੋਰੈਂਟ ਖਾਤਾ",
  "exportsLib.restaurantLedger.description": "ਪ੍ਰਾਪਤ ਖਰੀਦਾਂ, ਬਰਬਾਦੀ, ਸਟਾਫ ਖਾਣਾ ਅਤੇ ਵਿਧੀ ਖਪਤ ਇੱਕੋ ਖਾਤੇ ਵਿੱਚ: ਭਾਗ, ਤਾਰੀਖ, ਚੀਜ਼, ਮਾਤਰਾ, ਇਕਾਈ ਲਾਗਤ, ਕੁੱਲ ਲਾਗਤ ਅਤੇ ਹਵਾਲਾ।",
