  "apiErrors.invoiceFileNotFound": "ਉਹ ਇਨਵੌਇਸ ਫਾਈਲ ਰਿਕਾਰਡ ਵਿੱਚ ਨਹੀਂ ਹੈ।",
  "apiErrors.invoiceFileNotGranted": "ਸਿਰਫ਼ ਮਾਲਕ, ਜਾਂ ਟੀਮ ਦਾ ਉਹ ਮੈਂਬਰ ਜਿਸ 'ਤੇ ਪਕਵਾਨ-ਵਿਧੀਆਂ ਅਤੇ ਇਨਵੌਇਸ ਬਣਾਉਣ ਲਈ ਭਰੋਸਾ ਹੋਵੇ, ਇਨਵੌਇਸ ਫਾਈਲ ਬਦਲ ਸਕਦਾ ਹੈ।",
