  "training.own.titlePlaceholder": "ਇਸ ਸਿਖਲਾਈ ਦਾ ਨਾਮ ਰੱਖੋ…",
  "training.own.fieldMaterial": "ਸਿਖਲਾਈ ਆਪਣੇ ਆਪ",
  "training.own.materialPlaceholder": "ਆਪਣੀ ਸਿਖਲਾਈ ਇੱਥੇ ਲਿਖੋ…",
  "training.own.questionsHint": "ਇਸ ਸਿਖਲਾਈ ਦੀ ਕਵਿਜ਼ ਬਣਾਓ। ਬਹੁ-ਵਿਕਲਪੀ ਅਤੇ ਲਿਖਤੀ-ਜਵਾਬ ਸਵਾਲਾਂ ਨੂੰ ਖੁੱਲ੍ਹ ਕੇ ਮਿਲਾਓ — ਤੁਸੀਂ ਕਿੰਨੇ ਲਿਖਦੇ ਹੋ ਇਸਦੀ ਕੋਈ ਸੀਮਾ ਨਹੀਂ ਹੈ।",
