  "training.own.modeAuto": "ਉਨ੍ਹਾਂ ਨੂੰ ਮੇਰੀ ਜਵਾਬ-ਕੁੰਜੀ ਨਾਲ ਜਾਂਚੋ",
  "training.own.modeAutoHint": "ਟਾਈਪ ਕੀਤਾ ਜਵਾਬ ਜੋ ਤੁਹਾਡੇ ਉਮੀਦ ਕੀਤੇ ਜਵਾਬ ਨਾਲ ਲਗਭਗ ਸ਼ਬਦ-ਦਰ-ਸ਼ਬਦ ਮੇਲ ਖਾਂਦਾ ਹੈ, ਉਹ ਉਸੇ ਥਾਂ ਸਹੀ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਸਕੋਰ ਵਿੱਚ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ।",
  "training.own.modeReview": "ਮੁਲਾਂਕਣ ਲਈ ਮੇਰੇ ਕੋਲ ਭੇਜੋ",
  "training.own.modeReviewHint": "ਟਾਈਪ ਕੀਤੇ ਜਵਾਬ ਕੋਸ਼ਿਸ਼ ਦੇ ਨਾਲ ਤੁਹਾਡੇ ਕੋਲ ਆਉਂਦੇ ਹਨ, ਅਤੇ ਸਿਖਲਾਈ ਉਦੋਂ ਪੂਰੀ ਗਿਣੀ ਜਾਂਦੀ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਇਸਨੂੰ ਪਾਸ ਵਜੋਂ ਨਿਸ਼ਾਨ ਲਗਾਉਂਦੇ ਹੋ — ਜਾਂ ਇਸਨੂੰ ਦੁਬਾਰਾ ਲੈਣ ਲਈ ਵਾਪਸ ਭੇਜਦੇ ਹੋ।",
  "training.own.passLineHint": "ਇਸ ਸਿਖਲਾਈ ਨੂੰ ਪੂਰਾ ਕਰਨ ਲਈ ਵਿਅਕਤੀ ਨੂੰ ਲੋੜੀਂਦਾ ਸਕੋਰ।",
