  "training.own.assignNone": "ਅਜੇ ਕੋਈ ਟੀਮ ਮੈਂਬਰ ਨਹੀਂ — ਪਹਿਲਾਂ ਆਪਣੀ ਟੀਮ ਸ਼ਾਮਲ ਕਰੋ, ਫਿਰ ਟਿਕ ਕਰੋ ਕਿ ਇਹ ਕੌਣ ਲੈਂਦਾ ਹੈ।",
