  "checklists.starterCleaningItem3": "ਕੂੜਾ ਬਾਹਰ ਕੱਢੋ ਅਤੇ ਲਾਈਨਰ ਬਦਲੋ",
  "apiErrors.checklistsManage": "ਸਿਰਫ਼ ਮਾਲਕ, ਜਾਂ ਉਹ ਵਿਅਕਤੀ ਜਿਸਨੂੰ ਮਾਲਕ ਨੇ ਚੈੱਕਲਿਸਟ ਟੈਂਪਲੇਟ ਦੀ ਟਿਕ ਦਿੱਤੀ ਹੋਵੇ, ਚੈੱਕਲਿਸਟ ਟੈਂਪਲੇਟ ਬਦਲ ਸਕਦਾ ਹੈ।",
  "apiErrors.checklistProof": "ਇਸ ਚੀਜ਼ ਉੱਤੇ ਟਿਕ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਇਸਦਾ ਸਬੂਤ ਚਾਹੀਦਾ ਹੈ।",
  "apiErrors.checklistName": "ਚੈੱਕਲਿਸਟ ਨੂੰ ਇੱਕ ਨਾਂ ਦਿਓ।",
  "apiErrors.checklistItems": "ਚੈੱਕਲਿਸਟ ਵਿੱਚ ਘੱਟੋ-ਘੱਟ ਇੱਕ ਚੀਜ਼ ਜੋੜੋ।",
  "apiErrors.checklistUntick": "ਸਿਰਫ਼ ਉਹ ਵਿਅਕਤੀ ਜਿਸਨੇ ਇਸ ਚੀਜ਼ ਉੱਤੇ ਟਿਕ ਕੀਤਾ, ਕੋਈ ਮੈਨੇਜਰ, ਜਾਂ ਮਾਲਕ ਹੀ ਟਿਕ ਹਟਾ ਸਕਦਾ ਹੈ।",
  "training.lessons.staff-checklists.title": "ਚੈੱਕਲਿਸਟ ਉੱਤੇ ਕੰਮ ਕਰਨਾ",
  "training.lessons.staff-checklists.step1": "ਚੈੱਕਲਿਸਟਾਂ ਉਹ ਸੂਚੀਆਂ ਹਨ ਜਿਨ੍ਹਾਂ ਉੱਤੇ ਤੁਹਾਡਾ ਕਾਰੋਬਾਰ ਚੱਲਦਾ ਹੈ — ਖੋਲ੍ਹਣਾ, ਬੰਦ ਕਰਨਾ, ਸਫ਼ਾਈ, ਅਤੇ ਉਹ ਸਭ ਜੋ ਮਾਲਕ ਤੈਅ ਕਰੇ। ਇਹ ਚੈੱਕਲਿਸਟਾਂ ਵਿੱਚ ਮਿਲਣਗੀਆਂ: ਅੱਜ ਦੀਆਂ ਸੂਚੀਆਂ ਸਭ ਤੋਂ ਉੱਪਰ, ਟਿਕ ਕਰਨ ਲਈ ਤਿਆਰ।",
  "training.lessons.staff-checklists.step2": "ਕਿਸੇ ਚੀਜ਼ ਉੱਤੇ ਤਦ ਹੀ ਟਿਕ ਕਰੋ ਜਦੋਂ ਤੁਸੀਂ ਸੱਚਮੁੱਚ ਉਹ ਕਰ ਲਈ ਹੋਵੇ। ਹਰ ਟਿਕ ਲਿਖਦਾ ਹੈ ਕਿ ਕਿਸਨੇ ਕੀਤਾ ਅਤੇ ਕਦੋਂ, ਤਾਂ ਜੋ ਅਗਲਾ ਵਿਅਕਤੀ — ਅਤੇ ਘਰ ਬੈਠਾ ਮਾਲਕ — ਦੇਖ ਸਕੇ ਕਿ ਕੀ ਹੋ ਗਿਆ ਅਤੇ ਕੀ ਬਾਕੀ ਹੈ।",
  "training.lessons.staff-checklists.step3": "ਕੁਝ ਚੀਜ਼ਾਂ ਟਿਕ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਸਬੂਤ ਮੰਗਦੀਆਂ ਹਨ: ਪੂਰੇ ਕੰਮ ਦੀ ਫ਼ੋਟੋ, ਕਿਸੇ ਕੋਡ ਦਾ ਸਕੈਨ, ਜਾਂ ਲਿਖਿਆ ਤਾਪਮਾਨ। ਪਹਿਲਾਂ ਸਬੂਤ ਜੋੜੋ, ਫਿਰ ਟਿਕ ਕਰੋ — ਉਸ ਤੋਂ ਬਿਨਾਂ ਚੀਜ਼ ਟਿਕ ਨਹੀਂ ਹੋਵੇਗੀ।",
  "training.lessons.staff-checklists.step4": "ਗਲਤੀ ਨਾਲ ਕੁਝ ਟਿਕ ਕਰ ਦਿੱਤਾ? ਟਿਕ ਹਟਾਓ — ਪਰ ਸਿਰਫ਼ ਆਪਣੇ। ਮੈਨੇਜਰ ਜਾਂ ਮਾਲਕ ਕਿਸੇ ਦੀ ਵੀ ਟਿਕ ਹਟਾ ਸਕਦਾ ਹੈ, ਕਿਉਂਕਿ ਟਿਕ ਨਾਂ ਵਾਲਾ ਇੱਕ ਰਿਕਾਰਡ ਹੈ।",
  "training.lessons.staff-checklists.step5": "ਚੈੱਕਲਿਸਟ ਉੱਤੇ ਕੰਮ ਕਰਨ ਲਈ ਤੁਹਾਨੂੰ ਕਦੇ ਇਜਾਜ਼ਤ ਨਹੀਂ ਚਾਹੀਦੀ। ਟੈਂਪਲੇਟ ਬਣਾਉਣਾ ਅਤੇ ਇਹ ਚੁਣਨਾ ਕਿ ਉਹ ਕਿਸਨੂੰ ਸੌਂਪੇ ਜਾਣ, ਮਾਲਕ ਦਾ ਕੰਮ ਹੈ, ਜਾਂ ਉਸ ਵਿਅਕਤੀ ਦਾ ਜਿਸਨੂੰ ਮਾਲਕ ਨੇ ਚੈੱਕਲਿਸਟ ਟੈਂਪਲੇਟ ਦੀ ਟਿਕ ਦਿੱਤੀ ਹੋਵੇ।",
  "nav.safetyLogs": "ਭੋਜਨ ਸੁਰੱਖਿਆ ਲੌਗ",
  "nav.inspectionPacket": "ਨਿਰੀਖਣ ਪੈਕੇਟ",
  "nav.foodCerts": "ਭੋਜਨ ਸਰਟੀਫਿਕੇਟ",
  "nav.mockInspection": "ਨਕਲੀ ਨਿਰੀਖਣ",
  "nav.sds": "ਸੁਰੱਖਿਆ ਡੇਟਾ ਸ਼ੀਟਾਂ",
  "restaurant.doorSafetyLogs": "ਠੰਡਾ ਕਰਨਾ, ਦੁਬਾਰਾ ਗਰਮ ਕਰਨਾ ਅਤੇ ਸੈਨੀਟਾਈਜ਼ਰ ਜਾਂਚਾਂ, ਤਾਪਮਾਨ ਵਾਲੇ ਹੀ ਲੌਗ ਆਕਾਰ ਵਿੱਚ।",
  "restaurant.doorInspectionPacket": "ਨਿਰੀਖਕ ਦੀ ਤਾਰੀਖ ਸੀਮਾ ਦੇ ਸਾਰੇ ਲੌਗ, ਇੱਕ ਪੈਕੇਟ ਵਜੋਂ ਛਪੇ।",
  "restaurant.doorFoodCerts": "ਹਰ ਵਿਅਕਤੀ ਦੇ ਭੋਜਨ ਸਰਟੀਫਿਕੇਟ ਅਤੇ ਉਹ ਕਦੋਂ ਖਤਮ ਹੁੰਦੇ ਹਨ, ਖਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਚੇਤਾਵਨੀ ਨਾਲ।",
  "restaurant.doorMockInspection": "ਨਿਰੀਖਕ ਕੀ ਦੇਖਦਾ ਹੈ, ਉਸਦੀ ਦਿਸ਼ਾ-ਨਿਰਦੇਸ਼ਿਤ ਸੈਰ, ਚੈਕਲਿਸਟ ਇੰਜਣ ਉੱਤੇ।",
  "restaurant.doorSds": "ਤੁਹਾਡੇ ਰਸਾਇਣਾਂ ਦੀਆਂ ਸੁਰੱਖਿਆ ਡੇਟਾ ਸ਼ੀਟਾਂ, ਜਿੱਥੇ ਸਾਰੀ ਟੀਮ ਉਨ੍ਹਾਂ ਨੂੰ ਪੜ੍ਹ ਸਕਦੀ ਹੈ।",
  "plansLib.businessIncludes.foodSafetyFile": "ਰੈਸਟੋਰੈਂਟ, ਭੋਜਨ ਸੁਰੱਖਿਆ ਫਾਈਲ — ਠੰਡਾ ਕਰਨਾ, ਦੁਬਾਰਾ ਗਰਮ ਕਰਨਾ ਅਤੇ ਸੈਨੀਟਾਈਜ਼ਰ ਲੌਗ, ਨਿਰੀਖਣ-ਤਿਆਰ ਪੈਕੇਟ, ਭੋਜਨ-ਹੈਂਡਲਰ ਸਰਟੀਫਿਕੇਟ, ਨਕਲੀ ਨਿਰੀਖਣ ਅਤੇ ਸੁਰੱਖਿਆ ਡੇਟਾ ਸ਼ੀਟਾਂ",
  "foodSafety.correctiveRequired": "ਸੀਮਾ ਤੋਂ ਬਾਹਰ ਰੀਡਿੰਗ ਨੂੰ ਸੰਭਾਲਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਨੋਟ ਚਾਹੀਦਾ ਹੈ ਕਿ ਤੁਸੀਂ ਕੀ ਕੀਤਾ।",
  "apiErrors.correctiveAction": "ਸੀਮਾ ਤੋਂ ਬਾਹਰ ਰੀਡਿੰਗ ਨੂੰ ਸੰਭਾਲਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਨੋਟ ਚਾਹੀਦਾ ਹੈ ਕਿ ਤੁਸੀਂ ਕੀ ਕੀਤਾ।",
  "apiErrors.safetyLogKind": "ਇਸ ਤਰ੍ਹਾਂ ਦਾ ਭੋਜਨ ਸੁਰੱਖਿਆ ਲੌਗ ਮੌਜੂਦ ਨਹੀਂ ਹੈ।",
  "apiErrors.foodCertExpiry": "ਸਰਟੀਫਿਕੇਟ ਨੂੰ ਖਤਮ ਹੋਣ ਦੀ ਤਾਰੀਖ ਦਿਓ।",
  "apiErrors.foodSafetyRemoveOwnerOnly": "ਸਿਰਫ ਮਾਲਕ ਹੀ ਇਸਨੂੰ ਭੋਜਨ ਸੁਰੱਖਿਆ ਫਾਈਲ ਤੋਂ ਹਟਾ ਸਕਦਾ ਹੈ।",
  "foodSafety.logs.title": "ਠੰਡਾ ਕਰਨਾ, ਦੁਬਾਰਾ ਗਰਮ ਕਰਨਾ ਅਤੇ ਸੈਨੀਟਾਈਜ਼ਰ ਲੌਗ",
  "foodSafety.logs.subtitle": "ਭੋਜਨ ਲਈ ਠੰਡਾ ਕਰਨਾ ਅਤੇ ਦੁਬਾਰਾ ਗਰਮ ਕਰਨਾ ਜਾਂਚਾਂ, ਅਤੇ ਸੈਨੀਟਾਈਜ਼ਰ ਘੋਲ ਦੀ ਤਾਕਤ — ਕਿਸਨੇ ਜਾਂਚ ਕੀਤੀ, ਕਦੋਂ, ਅਤੇ ਕੀ ਇਹ ਸੁਰੱਖਿਅਤ ਸੀਮਾ ਵਿੱਚ ਸੀ।",
  "foodSafety.logs.newButton": "ਜਾਂਚ ਦਰਜ ਕਰੋ",
  "foodSafety.logs.dialogTitle": "ਭੋਜਨ ਸੁਰੱਖਿਆ ਜਾਂਚ ਦਰਜ ਕਰੋ",
  "foodSafety.logs.dialogIntro": "ਜੋ ਜਾਂਚ ਕੀਤੀ ਉਸਦਾ ਨਾਮ ਦਿਓ ਅਤੇ ਰੀਡਿੰਗ ਲਓ। ਸੀਮਾ ਤੋਂ ਬਾਹਰ ਰੀਡਿੰਗ ਨੂੰ ਸੰਭਾਲਣ ਤੋਂ ਪਹਿਲਾਂ ਉਸਦੀ ਸੁਧਾਰਾਤਮਕ ਕਾਰਵਾਈ ਚਾਹੀਦੀ ਹੈ।",
