  "foodSafety.certs.gatedNote": "ਸਰਟੀਫਿਕੇਟ ਸਟਾਫ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਨਾਲ ਜਾਂਦੇ ਹਨ: ਸਿਰਫ ਮਾਲਕ, ਜਾਂ ਉਹ ਮੈਨੇਜਰ ਜਿਸਨੂੰ ਮਾਲਕ ਨੇ ਸਟਾਫ ਦਸਤਾਵੇਜ਼ ਸੌਂਪੇ ਹਨ, ਉਨ੍ਹਾਂ ਨੂੰ ਸ਼ਾਮਲ ਜਾਂ ਬਦਲ ਸਕਦਾ ਹੈ। ਤੁਹਾਡੇ ਆਪਣੇ ਸਰਟੀਫਿਕੇਟ ਇੱਥੇ ਸੂਚੀਬੱਧ ਹਨ।",
