  "foodSafety.mock.title": "ਨਕਲੀ ਨਿਰੀਖਣ",
  "foodSafety.mock.subtitle": "ਨਿਰੀਖਕ ਦੇ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ, ਰਸੋਈ ਵਿੱਚ ਨਿਰੀਖਕ ਵਾਂਗ ਚੱਲੋ।",
  "foodSafety.mock.intro": "ਨਕਲੀ ਨਿਰੀਖਣ ਸ਼ੁਰੂ ਕਰੋ ਅਤੇ ਜਾਂਚ ਕਰਦੇ ਸਮੇਂ ਹਰ ਬਿੰਦੂ ਨੂੰ ਚੈਕਲਿਸਟ ਪੰਨੇ ਉੱਤੇ ਟਿਕ ਕਰੋ। ਹਰ ਟਿਕ ਦਰਜ ਕਰਦਾ ਹੈ ਕਿ ਕਿਸਨੇ ਅਤੇ ਕਦੋਂ ਜਾਂਚ ਕੀਤੀ — ਰਸਤੇ ਵਿੱਚ ਜੋ ਮਿਲੇ ਉਸਨੂੰ ਠੀਕ ਕਰੋ, ਅਤੇ ਫਾਈਲ ਕੰਮ ਦਿਖਾਏਗੀ।",
