  "foodSafety.mock.startedNote": "ਤੁਹਾਡਾ ਨਕਲੀ ਨਿਰੀਖਣ ਅੱਜ ਦੀਆਂ ਚੈਕਲਿਸਟਾਂ ਵਿੱਚ ਹੈ।",
  "foodSafety.mock.openChecklists": "ਚੈਕਲਿਸਟਾਂ ਖੋਲ੍ਹੋ",
  "foodSafety.mock.item1": "ਫਰਿੱਜ, ਫਰੀਜ਼ਰ ਅਤੇ ਗਰਮ ਰੱਖ-ਰਖਾਅ ਆਪਣੀਆਂ ਸੁਰੱਖਿਅਤ ਸੀਮਾਵਾਂ ਵਿੱਚ ਹਨ, ਅਤੇ ਤਾਪਮਾਨ ਲੌਗ ਭਰਿਆ ਹੋਇਆ ਹੈ।",
  "foodSafety.mock.item2": "ਠੰਡਾ ਕਰਨਾ ਅਤੇ ਦੁਬਾਰਾ ਗਰਮ ਕਰਨਾ ਜਾਂਚਾਂ ਦਰਜ ਹਨ, ਜਿੱਥੇ ਰੀਡਿੰਗ ਚੁੱਕੀ ਉੱਥੇ ਸੁਧਾਰਾਤਮਕ ਕਾਰਵਾਈ ਨਾਲ।",
