  "foodSafety.mock.item5": "ਸੁਰੱਖਿਆ ਡੇਟਾ ਸ਼ੀਟਾਂ ਉਸ ਸ਼ੈਲਫ ਉੱਤੇ ਹਨ ਜਿੱਥੇ ਸਾਰੀ ਟੀਮ ਉਨ੍ਹਾਂ ਨੂੰ ਪੜ੍ਹ ਸਕਦੀ ਹੈ।",
  "foodSafety.mock.item6": "ਤਾਰੀਖ ਵਾਲਾ ਭੋਜਨ ਲੇਬਲ ਕੀਤਾ ਹੋਇਆ ਹੈ ਅਤੇ ਸਮਾਪਤੀ ਕ੍ਰਮ ਵਿੱਚ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ: ਪਹਿਲਾਂ ਖਤਮ ਹੋਣ ਵਾਲਾ ਪਹਿਲਾਂ।",
