  "training.lessons.staff-food-safety.title": "ਭੋਜਨ ਸੁਰੱਖਿਆ ਫਾਈਲ ਰੱਖਣਾ",
  "training.lessons.staff-food-safety.step1": "ਭੋਜਨ ਸੁਰੱਖਿਆ ਫਾਈਲ ਰੈਸਟੋਰੈਂਟ ਕੋਨੇ ਦੀ ਭੋਜਨ ਸੁਰੱਖਿਆ ਸ਼ੈਲਫ ਉੱਤੇ ਰਹਿੰਦੀ ਹੈ: ਤਾਪਮਾਨ ਲੌਗ, ਠੰਡਾ ਕਰਨਾ, ਦੁਬਾਰਾ ਗਰਮ ਕਰਨਾ ਅਤੇ ਸੈਨੀਟਾਈਜ਼ਰ ਲੌਗ, ਸਰਟੀਫਿਕੇਟ, ਸੁਰੱਖਿਆ ਡੇਟਾ ਸ਼ੀਟਾਂ ਅਤੇ ਨਿਰੀਖਣ ਪੈਕੇਟ।",
  "training.lessons.staff-food-safety.step2": "ਸੀਮਾ ਤੋਂ ਬਾਹਰ ਰੀਡਿੰਗ ਉਦੋਂ ਤੱਕ ਪੂਰੀ ਨਹੀਂ ਹੁੰਦੀ ਜਦੋਂ ਤੱਕ ਉਸਦਾ ਨੋਟ ਨਾ ਕਹੇ ਕਿ ਤੁਸੀਂ ਕੀ ਕੀਤਾ — ਦੁਬਾਰਾ ਠੰਡਾ ਕੀਤਾ, ਦੁਬਾਰਾ ਗਰਮ ਕੀਤਾ, ਸੈਨੀਟਾਈਜ਼ਰ ਦੁਬਾਰਾ ਬਣਾਇਆ, ਸੁੱਟ ਦਿੱਤਾ। ਨੋਟ ਨਹੀਂ, ਸੰਭਾਲ ਨਹੀਂ: ਐਂਟਰੀ ਨਹੀਂ ਟਿਕਦੀ।",
  "training.lessons.staff-food-safety.step3": "ਠੰਡਾ ਕਰਨਾ, ਦੁਬਾਰਾ ਗਰਮ ਕਰਨਾ ਅਤੇ ਸੈਨੀਟਾਈਜ਼ਰ ਜਾਂਚਾਂ ਨੂੰ ਤਾਪਮਾਨ ਵਾਂਗ ਦਰਜ ਕਰੋ: ਤੁਸੀਂ ਕੀ ਜਾਂਚ ਕੀਤੀ, ਰੀਡਿੰਗ, ਅਤੇ ਚੁੱਕਣ ਉੱਤੇ ਸੁਧਾਰਾਤਮਕ ਕਾਰਵਾਈ।",
  "training.lessons.staff-food-safety.step4": "ਸਰਟੀਫਿਕੇਟ ਖਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਚੇਤਾਵਨੀ ਦਿੰਦੇ ਹਨ। ਜਦੋਂ ਤੁਹਾਡਾ ਚੇਤਾਵਨੀ ਦੇਵੇ, ਮਾਲਕ ਨੂੰ ਦੱਸੋ — ਅਤੇ ਕੋਈ ਵੀ ਸੁਰੱਖਿਆ ਡੇਟਾ ਸ਼ੀਟਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੀ ਸ਼ੈਲਫ ਉੱਤੇ ਕਿਸੇ ਵੀ ਸਮੇਂ ਪੜ੍ਹ ਸਕਦਾ ਹੈ।",
  "training.lessons.staff-food-safety.step5": "ਨਿਰੀਖਣ ਤੋਂ ਪਹਿਲਾਂ — ਜਾਂ ਕਿਸੇ ਵੀ ਸਮੇਂ — ਭੋਜਨ ਸੁਰੱਖਿਆ ਸ਼ੈਲਫ ਤੋਂ ਨਕਲੀ ਨਿਰੀਖਣ ਚਲਾਓ ਅਤੇ ਨਿਰੀਖਕ ਦੀਆਂ ਤਾਰੀਖਾਂ ਲਈ ਨਿਰੀਖਣ-ਤਿਆਰ ਪੈਕੇਟ ਛਾਪੋ।",
  "nav.kitchenDisplay": "ਰਸੋਈ ਡਿਸਪਲੇ",
  "nav.guestMenu": "ਮਹਿਮਾਨ ਮੀਨੂ",
  "restaurant.doorKitchenDisplay": "ਰਸੋਈਏ ਲਈ ਉਸਦੇ ਸਟੇਸ਼ਨ 'ਤੇ ਇੱਕ ਵਿਅੰਜਨ ਦਾ ਵੱਡਾ, ਸਪੱਸ਼ਟ ਦ੍ਰਿਸ਼।",
  "restaurant.doorGuestMenu": "ਉਹ ਮੀਨੂ ਜੋ ਤੁਹਾਡੇ ਮਹਿਮਾਨ ਵੇਖਦੇ ਹਨ, ਤੁਹਾਡੇ ਪਕਵਾਨਾਂ ਅਤੇ ਕੀਮਤਾਂ ਤੋਂ ਬਣਿਆ।",
  "plansLib.businessIncludes.kitchenDisplay": "ਰੈਸਟੋਰੈਂਟ, ਰਸੋਈ ਡਿਸਪਲੇ — ਇੱਕ ਵਿਅੰਜਨ, ਵੱਡਾ ਅਤੇ ਸਪੱਸ਼ਟ, ਬੈਚ ਅਨੁਸਾਰ ਬਦਲਦੀਆਂ ਮਾਤਰਾਵਾਂ ਨਾਲ",
  "plansLib.businessIncludes.guestMenuPage": "ਰੈਸਟੋਰੈਂਟ, ਮਹਿਮਾਨ ਮੀਨੂ ਪੰਨਾ — ਤੁਹਾਡੇ ਪਕਵਾਨਾਂ, ਕੀਮਤਾਂ ਅਤੇ ਐਲਰਜੀ ਰਿਕਾਰਡ ਤੋਂ ਸਾਂਝਾ ਕਰਨ ਯੋਗ ਮੀਨੂ",
