  "training.lessons.staff-kitchen-menu.title": "ਰਸੋਈ ਡਿਸਪਲੇ ਅਤੇ ਮਹਿਮਾਨ ਮੀਨੂ ਨਾਲ ਖਾਣਾ ਬਣਾਉਣਾ",
  "training.lessons.staff-kitchen-menu.step1": "ਰਸੋਈ ਅਤੇ ਵਿਅੰਜਨ ਸ਼ੈਲਫ਼ ਤੋਂ ਰਸੋਈ ਡਿਸਪਲੇ ਖੋਲ੍ਹੋ ਅਤੇ ਉਹ ਵਿਅੰਜਨ ਚੁਣੋ ਜੋ ਤੁਸੀਂ ਬਣਾ ਰਹੇ ਹੋ।",
  "training.lessons.staff-kitchen-menu.step2": "ਛੂਹ ਕੇ ਦੱਸੋ ਕਿੰਨੇ ਬੈਚ ਬਣਾ ਰਹੇ ਹੋ। ਸਕ੍ਰੀਨ 'ਤੇ ਹਰ ਮਾਤਰਾ ਉਸ ਅਨੁਸਾਰ ਹੋ ਜਾਵੇਗੀ — ਯਾਦ ਨਾਲ ਨਹੀਂ, ਸਕ੍ਰੀਨ ਤੋਂ ਬਣਾਓ।",
  "training.lessons.staff-kitchen-menu.step3": "ਡਿਸਪਲੇ ਵਿਅੰਜਨ ਦੀ ਤਸਵੀਰ, ਤੁਹਾਡੀ ਬੈਚ ਗਿਣਤੀ ਅਨੁਸਾਰ ਉਸਦੀ ਸਮੱਗਰੀ ਅਤੇ ਕ੍ਰਮ ਵਿੱਚ ਉਸਦੇ ਕਦਮ ਵਿਖਾਉਂਦਾ ਹੈ।",
  "training.lessons.staff-kitchen-menu.step4": "ਮਹਿਮਾਨ ਮੀਨੂ ਸਿਰਫ਼ ਉਹੀ ਪਕਵਾਨ ਵਿਖਾਉਂਦਾ ਹੈ ਜਿਨ੍ਹਾਂ 'ਤੇ ਮਾਲਕ ਨੇ ਨਿਸ਼ਾਨ ਲਗਾਇਆ ਹੋਵੇ। ਕੀਮਤਾਂ ਅਤੇ ਐਲਰਜੀ ਨਿਸ਼ਾਨ ਰਿਕਾਰਡਾਂ ਤੋਂ ਆਉਂਦੇ ਹਨ, ਦੁਬਾਰਾ ਲਿਖਣ ਨਾਲ ਕਦੇ ਨਹੀਂ।",
  "training.lessons.staff-kitchen-menu.step5": "ਮੀਨੂ ਦਾ ਲਿੰਕ ਮਹਿਮਾਨਾਂ ਨਾਲ ਸਾਂਝਾ ਕਰੋ ਜਾਂ ਮੀਨੂ ਛਾਪੋ। ਪੜ੍ਹਨ ਲਈ ਮਹਿਮਾਨਾਂ ਨੂੰ ਖਾਤੇ ਦੀ ਲੋੜ ਨਹੀਂ।",
