  "plansLib.includes.equipment": "ਉਪਕਰਣ ਰਿਕਾਰਡ — ਹਰ ਮਸ਼ੀਨ, ਉਸਦੀ ਦੇਖਭਾਲ, ਉਸਦੀਆਂ ਮੁਰੰਮਤਾਂ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਲਾਗਤ",
