  "equipment.manageHint": "ਮਸ਼ੀਨ ਪੰਨੇ, ਦੇਖਭਾਲ ਸਮਾਂ-ਸਾਰਣੀਆਂ ਅਤੇ ਮੁਰੰਮਤਾਂ ਮਾਲਕ ਅਤੇ ਮੈਨੇਜਰਾਂ ਦੀਆਂ ਹਨ। ਜਿਸਨੂੰ ਮਾਲਕ ਖਰਾਬੀ ਦਾ ਨਿਸ਼ਾਨ ਦੇਵੇ, ਉਹ ਖਰਾਬੀ ਦੀ ਰਿਪੋਰਟ ਕਰ ਸਕਦਾ ਹੈ।",
