  "apiErrors.equipmentReport": "ਖਰਾਬੀ ਦੀ ਰਿਪੋਰਟ ਸਿਰਫ਼ ਮਾਲਕ, ਮੈਨੇਜਰ, ਜਾਂ ਉਹ ਵਿਅਕਤੀ ਕਰ ਸਕਦਾ ਹੈ ਜਿਸਨੂੰ ਮਾਲਕ ਨੇ ਖਰਾਬੀ ਰਿਪੋਰਟ ਦਾ ਨਿਸ਼ਾਨ ਦਿੱਤਾ ਹੋਵੇ।",
  "apiErrors.equipmentName": "ਮਸ਼ੀਨ ਨੂੰ ਨਾਮ ਦਿਓ।",
  "apiErrors.equipmentRepair": "ਮੁਰੰਮਤ ਅਤੇ ਉਸਦੀ ਲਾਗਤ ਸਿਰਫ਼ ਮਾਲਕ ਜਾਂ ਮੈਨੇਜਰ ਦਰਜ ਕਰ ਸਕਦਾ ਹੈ।",
  "apiErrors.equipmentUpkeepName": "ਦੇਖਭਾਲ ਕੰਮ ਨੂੰ ਨਾਮ ਦਿਓ।",
  "apiErrors.equipmentBreakdownWhat": "ਦੱਸੋ ਕੀ ਟੁੱਟਿਆ।",
  "training.lessons.staff-equipment.title": "ਉਪਕਰਣ ਰਿਕਾਰਡ ਅਤੇ ਖਰਾਬੀ ਦੀ ਰਿਪੋਰਟ ਕਰਨਾ",
  "training.lessons.staff-equipment.step1": "ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਦੀ ਹਰ ਮਸ਼ੀਨ ਦਾ ਉਪਕਰਣਾਂ ਵਿੱਚ ਆਪਣਾ ਪੰਨਾ ਹੈ: ਕਦੋਂ ਖਰੀਦੀ ਗਈ, ਵਾਰੰਟੀ ਕਦੋਂ ਖਤਮ ਹੁੰਦੀ ਹੈ, ਸਰਵਿਸ ਕੌਣ ਕਰਦਾ ਹੈ, ਅਤੇ ਉਸ ਨਾਲ ਜੋ ਕੁਝ ਹੋਇਆ।",
  "training.lessons.staff-equipment.step2": "ਜਦੋਂ ਕੁਝ ਟੁੱਟੇ, ਉਸਦੀ ਰਿਪੋਰਟ ਮਸ਼ੀਨ ਉੱਤੇ ਹੀ ਕਰੋ। ਦੱਸੋ ਕੀ ਟੁੱਟਿਆ, ਅਤੇ ਹੋ ਸਕੇ ਤਾਂ ਸਮੱਸਿਆ ਦੀ ਫੋਟੋ ਜੋੜੋ — ਰਿਪੋਰਟ ਤੁਹਾਡੇ ਨਾਮ ਅਤੇ ਸਮੇਂ ਨਾਲ ਮਸ਼ੀਨ ਦੇ ਇਤਿਹਾਸ ਵਿੱਚ ਜਾਂਦੀ ਹੈ।",
  "training.lessons.staff-equipment.step3": "ਤੁਸੀਂ ਖਰਾਬੀ ਦੀ ਰਿਪੋਰਟ ਤਾਂ ਹੀ ਕਰ ਸਕਦੇ ਹੋ ਜੇ ਮਾਲਕ ਨੇ ਤੁਹਾਨੂੰ ਖਰਾਬੀ ਰਿਪੋਰਟ ਦਾ ਨਿਸ਼ਾਨ ਦਿੱਤਾ ਹੋਵੇ। ਜੇ ਬਟਨ ਉੱਥੇ ਨਹੀਂ ਹੈ, ਤਾਂ ਮਾਲਕ ਜਾਂ ਮੈਨੇਜਰ ਨੂੰ ਦੱਸੋ, ਉਹ ਤੁਹਾਡੇ ਲਈ ਦਰਵਾਜ਼ਾ ਖੋਲ੍ਹਣਗੇ।",
  "training.lessons.staff-equipment.step4": "ਦੇਖਭਾਲ ਕੰਮਾਂ ਦੀਆਂ — ਸਫ਼ਾਈ, ਡੀਸਕੇਲਿੰਗ, ਸਰਵਿਸ — ਬਕਾਇਆ ਤਾਰੀਖਾਂ ਹੁੰਦੀਆਂ ਹਨ। ਉਪਕਰਣ ਪੰਨਾ ਦਿਖਾਉਂਦਾ ਹੈ ਕੀ ਬਕਾਇਆ ਹੈ ਅਤੇ ਕੀ ਮਿਆਦ ਲੰਘਿਆ, ਤਾਂ ਜੋ ਕੁਝ ਚੁੱਪਚਾਪ ਨਾ ਰਹਿ ਜਾਵੇ।",
  "training.lessons.staff-equipment.step5": "ਮੁਰੰਮਤਾਂ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਲਾਗਤ ਮਾਲਕ ਜਾਂ ਮੈਨੇਜਰ ਦਰਜ ਕਰਦਾ ਹੈ। ਜਦੋਂ ਤੁਹਾਡੀ ਰਿਪੋਰਟ ਉੱਤੇ ਮੁਰੰਮਤ ਦਰਜ ਹੋ ਜਾਵੇ, ਤਾਂ ਖਰਾਬੀ ਮਸ਼ੀਨ ਦੇ ਇਤਿਹਾਸ ਵਿੱਚ ਠੀਕ ਹੋਈ ਦਿਖਦੀ ਹੈ।",
  "nav.tipPooling": "ਟਿਪ ਪੂਲ",
  "plansLib.businessIncludes.tipPooling": "ਟਿਪ ਪੂਲ ਅਤੇ ਟਿਪ ਰਿਕਾਰਡ — ਪੂਲ ਨੂੰ ਆਪਣੇ ਤਰੀਕੇ ਨਾਲ ਵੰਡੋ ਅਤੇ ਸਾਲ ਦਾ ਟਿਪ ਰਿਕਾਰਡ ਰੱਖੋ",
  "restaurant.doorTipPooling": "ਟਿਪ ਪੂਲ ਵੰਡੋ ਅਤੇ ਸਾਲ ਦਾ ਟਿਪ ਰਿਕਾਰਡ ਰੱਖੋ।",
  "tipPooling.title": "ਟਿਪ ਪੂਲ",
  "tipPooling.subtitle": "ਟਿਪ ਪੂਲ ਨੂੰ ਉਸੇ ਤਰ੍ਹਾਂ ਵੰਡੋ ਜਿਵੇਂ ਤੁਸੀਂ ਸੈੱਟ ਕੀਤਾ ਹੈ, ਅਤੇ ਆਪਣੀ ਟੀਮ ਵੱਲੋਂ ਦੱਸੀਆਂ ਟਿਪਾਂ ਦਾ ਸਾਲ ਦਾ ਰਿਕਾਰਡ ਰੱਖੋ।",
  "tipPooling.ownerOnlyNote": "ਪੂਲ ਦਾ ਸੈੱਟਅੱਪ, ਹਿੱਸੇ ਅਤੇ ਰਿਕਾਰਡ ਤੁਹਾਡੇ ਨੰਬਰ ਹਨ। ਟੀਮ ਮੈਂਬਰ ਸਿਰਫ਼ ਆਪਣਾ ਹਿੱਸਾ ਵੇਖਦਾ ਹੈ, ਅਤੇ ਸਿਰਫ਼ ਉਸ ਵੰਡ ਲਈ ਜੋ ਤੁਸੀਂ ਪ੍ਰਕਾਸ਼ਿਤ ਕੀਤੀ ਹੈ।",
