  "tipPooling.recordsTitle": "ਟਿਪ ਰਿਪੋਰਟਿੰਗ ਰਿਕਾਰਡ",
  "tipPooling.recordsSubtitle": "ਹਰ ਵਿਅਕਤੀ ਲਈ, ਹਰ ਮਿਆਦ ਲਈ: ਦੱਸੀਆਂ ਟਿਪਾਂ, ਉਨ੍ਹਾਂ ਦੀ ਕੁੱਲ ਪ੍ਰਾਪਤੀ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਘੰਟੇ — 8% ਹਿਸਾਬ ਸਾਲ ਦੇ ਰਿਕਾਰਡ ਵੱਲੋਂ ਮੰਗੇ ਕੁੱਲਾਂ ਵਿੱਚ ਬਦਲਿਆ ਹੋਇਆ। ਇਹ ਪੰਨਾ ਸਿਰਫ਼ ਰਿਕਾਰਡ ਰੱਖਦਾ ਹੈ; ਇਹ ਕੁਝ ਦਾਖਲ ਨਹੀਂ ਕਰਦਾ।",
